        <div className="w-18 h-28 sm:w-24 sm:h-36 bg-white rounded-xl flex flex-col items-center justify-center border-2 border-slate-300 shadow-[0_10px_20px_rgba(0,0,0,0.5)] animate-in zoom-in duration-300 relative overflow-hidden">
             <div className={`absolute top-1 left-2 font-black text-lg ${card.suit==='♥'||card.suit==='♦'?'text-red-600':'text-slate-900'}`}>{card.rank}</div>
             <div className={`text-5xl ${card.suit==='♥'||card.suit==='♦'?'text-red-600':'text-slate-900'}`}>{card.suit}</div>
             <div className={`absolute bottom-1 right-2 font-black text-lg rotate-180 ${card.suit==='♥'||card.suit==='♦'?'text-red-600':'text-slate-900'}`}>{card.rank}</div>
        </div>
    );

    return (
        <div className="bg-[#051c14] min-h-screen flex flex-col font-sans text-white select-none overflow-x-hidden relative">
            {showBalanceError && (
                <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[200] bg-red-600 px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 border border-red-400 animate-in slide-in-from-top-4">
                    <AlertCircle className="text-white" size={20}/>
