                        {[10, 100, 500, 1000, 5000].map(a => <button key={a} onClick={() => setBetAmount(a)} className={`px-5 py-3 rounded-2xl font-black text-xs border transition-all ${betAmount === a ? 'bg-yellow-500 text-black border-white shadow-xl scale-110' : 'bg-zinc-900 text-zinc-600 border-white/5'}`}>₹{a >= 1000 ? `${a/1000}K` : a}</button>)}
