                             <button onClick={() => setShowRules(false)} className="p-3 bg-slate-800 rounded-full active:scale-90"><X size={24}/></button>
                         </div>
                         <div className="space-y-4 text-sm text-emerald-100 font-medium leading-relaxed">
                             <p>1. Predict the winning hand closest to <span className="text-yellow-500 font-bold">9</span> points.</p>
                             <p>2. <span className="text-white font-bold">10, J, Q, K</span> are worth <span className="text-yellow-500">0</span>. Aces are <span className="text-yellow-500">1</span>.</p>
                             <p>3. If hand sum > 9, only the <span className="text-yellow-500 font-bold">right digit</span> counts (e.g., 15 becomes 5).</p>
                             <div className="bg-black/40 p-5 rounded-2xl border border-white/10 mt-6 shadow-inner">
                                <h4 className="text-[10px] font-black text-yellow-500 mb-4 uppercase tracking-[0.3em]">UNDERWORLD PAYOUTS</h4>
                                <div className="flex justify-between mb-2"><span>Player Win</span><span className="font-black text-blue-400">2.00x</span></div>
                                <div className="flex justify-between mb-2"><span>Banker Win</span><span className="font-black text-red-500">2.00x</span></div>
                                <div className="flex justify-between"><span>Tie Bonus</span><span className="font-black text-green-500">9.00x</span></div>
                             </div>
                         </div>
                    </div>
                </div>
            )}
        </div>
    );
};
export default Baccarat;

import React, { useState, useEffect } from 'react';
import NavBar from './components/NavBar';
