import GameResultPopup from './components/GameResultPopup';
import { View, UserProfile, GameResult } from './types';
import { subscribeToBalance, startGlobalEngines, stopAllSounds } from './services/mockFirebase';

export default function App() {
  const [currentView, setCurrentView] = useState<View>('HOME');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [gameResult, setGameResult] = useState<GameResult | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => { 
      startGlobalEngines(); 
  }, []);

  useEffect(() => { 
      stopAllSounds(); 
  }, [currentView]);

  useEffect(() => {
    const unsubscribe = subscribeToBalance((updatedUser) => {
        setUser(updatedUser);
        setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  if (isLoading) return (
    <div className="min-h-screen bg-[#0a0f1d] flex items-center justify-center">
      <div className="w-12 h-12 border-4 border-yellow-500 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!user && currentView !== 'LOGIN' && currentView !== 'REGISTER') {
    return <Auth />;
  }

  const renderContent = () => {
    if (!user) return <Auth />;

    switch (currentView) {
      case 'HOME': return <Home setView={setCurrentView} />;
      case 'GAME_WINGO': return <WinGo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} setView={setCurrentView} />;
      case 'GAME_AVIATOR': return <Aviator onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_MINES': return <Mines onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DRAGON_TIGER': return <DragonTiger onBack={() => setCurrentView('HOME')} userBalance={user.balance} username={user.username} onResult={setGameResult} />;
      case 'GAME_ROULETTE': return <Roulette onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_SICBO': return <SicBo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_BACCARAT': return <Baccarat onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_STREET_RACE': return <StreetRace onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_VAULT': return <VaultBreaker onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_FRUIT_SLOT': return <FruitSlot onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_EGYPT_SLOT': return <EgyptSlot onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DICE': return <DiceDuel onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_MOTO_RACING': return <MotoRacing onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_PLINKO': return <Plinko onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_LIMBO': return <Limbo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_HILO': return <HiLo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DRAGON_TOWER': return <DragonTower onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_KENO': return <Keno onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_HEAD_TAILS': return <HeadTails onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DOG': return <WinGo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} setView={setCurrentView} />;
      case 'GAME_VORTEX': return <Limbo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'ACCOUNT': return <Profile user={user} setView={setCurrentView} />;
      case 'REFERRAL': return <Referral user={user} />;
      case 'PROMOTION': return <Promotion />;
      case 'WALLET': return <Wallet setView={setCurrentView} userBalance={user.balance} />;
      case 'DEPOSIT': return <Deposit onBack={() => setCurrentView('WALLET')} />;
      case 'WITHDRAW': return <Withdraw onBack={() => setCurrentView('WALLET')} userBalance={user.balance} />;
      case 'SAFETY': return <SafetyCenter setView={setCurrentView} user={user} />;
      case 'STATISTICS': return <GameStatistics setView={setCurrentView} />;
      case 'REWARDS_HUB': return <BindingRewards onBack={() => setCurrentView('ACCOUNT')} />;
      default: return <Home setView={setCurrentView} />;
    }
  };

  const showNavBar = ['HOME', 'REFERRAL', 'PROMOTION', 'WALLET', 'ACCOUNT'].includes(currentView);

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0a0f1d] shadow-2xl relative overflow-hidden font-sans border-x border-white/5">
      {renderContent()}
      <GameResultPopup result={gameResult} onClose={() => setGameResult(null)} />
      {showNavBar && <NavBar currentView={currentView} setView={setCurrentView} />}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, History, X, AlertCircle } from 'lucide-react';
import { updateBalance, subscribeToDragonTiger, playSound, addGameHistory, stopAllSounds } from '../services/mockFirebase';
import { DragonTigerState, GameResult } from '../types';

interface Props {
    onBack: () => void;
    userBalance: number;
    username: string;
    onResult: (r: GameResult) => void;
}

interface UserBet {
    id: string;
    target: 'D' | 'T' | 'Tie';
    amount: number;
}

const DragonTiger: React.FC<Props> = ({ onBack, userBalance, username, onResult }) => {
    const [gameState, setGameState] = useState<DragonTigerState | null>(null);
    const [selectedChip, setSelectedChip] = useState(10);
    const [myBets, setMyBets] = useState<UserBet[]>([]);
    const [showDragon, setShowDragon] = useState(false);
    const [showTiger, setShowTiger] = useState(false);
    const [confirmDrawerOpen, setConfirmDrawerOpen] = useState(false);
    const [confirmTarget, setConfirmTarget] = useState<'D' | 'T' | 'Tie' | null>(null);
    const [showBalanceError, setShowBalanceError] = useState(false);

    const isMounted = useRef(true);
    const resultHandledRef = useRef<string | null>(null);

    useEffect(() => {
        isMounted.current = true;
        const unsub = subscribeToDragonTiger((state) => {
            if (!isMounted.current) return;
            setGameState(state);
            if (state.status === 'BETTING') {
                setShowDragon(false); setShowTiger(false); resultHandledRef.current = null;
                if (state.timeLeft <= 5 && state.timeLeft > 0) playSound('wingo_tick');
            }
            if (state.status === 'RESULT' && resultHandledRef.current !== state.period) {
                resultHandledRef.current = state.period;
                handleRevealingSequence(state);
            }
        });
        return () => { isMounted.current = false; unsub(); stopAllSounds(); };
    }, []);

    const handleRevealingSequence = async (state: DragonTigerState) => {
        await new Promise(r => setTimeout(r, 800));
        if (!isMounted.current) return;
        setShowDragon(true);
        playSound('dt_card');
        await new Promise(r => setTimeout(r, 1200));
        if (!isMounted.current) return;
        setShowTiger(true);
        playSound('dt_card');
        await new Promise(r => setTimeout(r, 1000));
        if (isMounted.current && myBets.length > 0) {
            playSound('dt_draw');
            processMyResult(state);
        }
    };

    const processMyResult = (state: DragonTigerState) => {
        const dVal = state.dragonCard!;
        const tVal = state.tigerCard!;
        const winner = dVal > tVal ? 'D' : tVal > dVal ? 'T' : 'Tie';
        let totalWin = 0; let totalBet = 0;
        myBets.forEach(bet => {
            totalBet += bet.amount;
            if (bet.target === winner) totalWin += bet.amount * (winner === 'Tie' ? 9 : 2);
        });

        if (totalWin > 0) { 
            updateBalance(totalWin, 'WIN', 'Dragon Tiger Win'); 
            playSound('win'); 
            onResult({ win: true, amount: totalWin, game: 'Dragon Tiger' }); 
        } else { 
            playSound('loss'); 
            onResult({ win: false, amount: totalBet, game: 'Dragon Tiger' }); 
        }
        addGameHistory('Dragon Tiger', totalBet, totalWin, `Outcome: ${winner}`);
        setMyBets([]);
    };

    const handleTargetClick = (target: 'D' | 'T' | 'Tie') => {
        if (gameState?.status !== 'BETTING' || gameState!.timeLeft <= 3) return;
        setConfirmTarget(target);
        setConfirmDrawerOpen(true);
        playSound('click');
    };

    const confirmBetAction = () => {
        if (selectedChip > userBalance) {
            setShowBalanceError(true);
            setTimeout(() => setShowBalanceError(false), 3000);
            setConfirmDrawerOpen(false);
            return;
        }
        updateBalance(-selectedChip, 'BET', `DT Bet on ${confirmTarget}`);
        setMyBets(prev => [...prev, { id: Date.now().toString(), target: confirmTarget!, amount: selectedChip }]);
        setConfirmDrawerOpen(false);
        playSound('click');
    };

    const getCardRank = (val: number) => {
        if (val === 1) return 'A';
        if (val === 11) return 'J';
        if (val === 12) return 'Q';
        if (val === 13) return 'K';
        return val.toString();
    };

    if (!gameState) return <div className="min-h-screen bg-black flex items-center justify-center font-black gold-text animate-pulse">Entering Arena...</div>;

    const currentTotalStaked = myBets.reduce((a, b) => a + b.amount, 0);

    return (
        <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white select-none overflow-hidden relative">
            {showBalanceError && (
                <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[200] bg-red-600 px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 border border-red-400 animate-in slide-in-from-top-4">
                    <AlertCircle className="text-white" size={20}/>
                    <span className="font-black text-xs uppercase tracking-widest italic">Insufficient Balance! Please deposit to continue.</span>
                </div>
            )}

            <div className="p-4 flex justify-between items-center bg-[#111827] border-b border-yellow-500/20 shadow-2xl relative z-50">
                <div className="flex items-center gap-3">
                    <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl active:scale-90"><ArrowLeft size={20}/></button>
                    <h1 className="text-lg font-black italic gold-text uppercase">DRAGON TIGER</h1>
                </div>
                <div className="bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20 text-yellow-500 font-mono shadow-inner flex items-center gap-2">
                    <Wallet size={14} />
                    <span>₹{userBalance.toFixed(2)}</span>
                </div>
            </div>

            <div className="flex-1 bg-gradient-to-b from-[#064e3b] via-[#0a0f1d] to-[#0a0f1d] flex flex-col items-center justify-center gap-12 relative">
                <div className="absolute top-4 left-1/2 -translate-x-1/2 z-10">
                    <div className={`w-20 h-20 rounded-full border-4 flex flex-col items-center justify-center font-black shadow-2xl bg-black/40 backdrop-blur-sm ${gameState.status === 'BETTING' ? 'border-green-500 text-green-500' : 'border-red-600 text-red-600 animate-pulse'}`}>
                        <span className="text-[10px] uppercase opacity-50">Timer</span>
                        <span className="text-3xl italic leading-none">{gameState.timeLeft}</span>
                    </div>
                </div>

                <div className="flex justify-center items-center gap-8 w-full px-4 relative z-0">
                    <div className={`w-36 h-52 rounded-2xl border-4 transition-all duration-700 perspective-1000 ${showDragon ? 'border-red-500 bg-white rotate-y-180 scale-105 shadow-[0_0_30px_rgba(239,68,68,0.4)]' : 'border-white/10 bg-slate-900'} flex flex-col items-center justify-center shadow-2xl relative overflow-hidden`}>
                        {showDragon ? (
                            <>
                                <span className={`text-7xl font-black ${[1,2].includes(Math.random())?'text-red-600':'text-slate-900'}`}>{getCardRank(gameState.dragonCard!)}</span>
                                <span className="absolute bottom-2 font-black text-xs text-red-500 tracking-widest uppercase">Dragon</span>
                            </>
                        ) : <span className="text-5xl opacity-10 font-black italic">D</span>}
                    </div>
                    <span className="text-4xl font-black italic gold-text animate-pulse">VS</span>
                    <div className={`w-36 h-52 rounded-2xl border-4 transition-all duration-700 perspective-1000 ${showTiger ? 'border-orange-500 bg-white rotate-y-180 scale-105 shadow-[0_0_30px_rgba(249,115,22,0.4)]' : 'border-white/10 bg-slate-900'} flex flex-col items-center justify-center shadow-2xl relative overflow-hidden`}>
                        {showTiger ? (
                            <>
