interface Ball {
  id: string; x: number; y: number; row: number; col: number; bet: number;
  status: 'DROPPING' | 'DONE'; targetX: number; targetY: number; progress: number;
  startPos: { x: number; y: number };
}

const MULTIPLIERS = [10, 5, 2, 1.2, 0.5, 1.2, 2, 5, 10];
const ROWS = 9; const PIN_RADIUS = 5; const BALL_RADIUS = 8;
const CANVAS_WIDTH = 380; const CANVAS_HEIGHT = 540;

const Plinko: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; }> = ({ onBack, userBalance, onResult }) => {
  const [betAmount, setBetAmount] = useState(10);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showRules, setShowRules] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>([]);
  const pulsesRef = useRef<{row: number, col: number, startTime: number}[]>([]);
  const requestRef = useRef<number>(0);
  const [floatingResults, setFloatingResults] = useState<{ id: string; mult: number; amount: number }[]>([]);

  const startY = 110; const rowSpacing = 40; const colSpacing = 36;

  useEffect(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    const animate = () => { updatePhysics(); draw(ctx); requestRef.current = requestAnimationFrame(animate); };
    requestRef.current = requestAnimationFrame(animate);
    return () => { cancelAnimationFrame(requestRef.current); stopAllSounds(); };
  }, []);

  const getPinCoords = (row: number, col: number) => {
    const pinsInRow = row + 1; const rowWidth = (pinsInRow - 1) * colSpacing;
    const startX = (CANVAS_WIDTH - rowWidth) / 2;
    return { x: startX + col * colSpacing, y: startY + row * rowSpacing };
  };

  const updatePhysics = () => {
    const slotY = startY + ROWS * rowSpacing + 20; const speed = 0.12; 
    ballsRef.current = ballsRef.current.map(ball => {
      if (ball.status === 'DONE') return ball;
      ball.progress += speed;
      if (ball.progress >= 1) {
        ball.x = ball.targetX; ball.y = ball.targetY; ball.progress = 0; ball.startPos = { x: ball.x, y: ball.y };
        if (ball.row < ROWS - 1) {
          pulsesRef.current.push({ row: ball.row, col: ball.col, startTime: Date.now() });
          playSound('wingo_tick');
          const nextRow = ball.row + 1; const moveRight = Math.random() > 0.49 ? 1 : 0;
          const nextCol = ball.col + moveRight; const coords = getPinCoords(nextRow, nextCol);
          return { ...ball, row: nextRow, col: nextCol, targetX: coords.x, targetY: coords.y };
        } else {
          if (ball.y < slotY) { playSound('wingo_tick'); return { ...ball, targetY: slotY + 25, targetX: ball.x, row: ROWS }; }
          else { handleBallLand(ball); return { ...ball, status: 'DONE' }; }
        }
      }
      const t = ball.progress; const arcHeight = 10; 
      ball.x = ball.startPos.x + (ball.targetX - ball.startPos.x) * t;
      const linearY = ball.startPos.y + (ball.targetY - ball.startPos.y) * t;
      ball.y = linearY - (-4 * arcHeight * t * (t - 1));
      return ball;
    }).filter(b => b.status === 'DROPPING');
    pulsesRef.current = pulsesRef.current.filter(p => Date.now() - p.startTime < 400);
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    for (let r = 0; r < ROWS; r++) {
      const pinsInRow = r + 1; const rowWidth = (pinsInRow - 1) * colSpacing;
      const startX = (CANVAS_WIDTH - rowWidth) / 2;
      for (let p = 0; p < pinsInRow; p++) {
        const px = startX + p * colSpacing; const py = startY + r * rowSpacing;
        const pulse = pulsesRef.current.find(pulse => pulse.row === r && pulse.col === p);
        const scale = pulse ? 1 + 0.5 * Math.sin((Date.now() - pulse.startTime) / 40) : 1;
        ctx.beginPath(); ctx.arc(px, py, PIN_RADIUS * scale, 0, Math.PI * 2);
        ctx.fillStyle = pulse ? '#60A5FA' : 'rgba(203, 213, 225, 0.8)'; ctx.fill();
      }
    }
    const slotY = startY + ROWS * rowSpacing + 20; const totalSlotWidth = MULTIPLIERS.length * colSpacing;
    const slotStartX = (CANVAS_WIDTH - totalSlotWidth + 4) / 2;
    MULTIPLIERS.forEach((m, i) => {
      const sx = slotStartX + i * colSpacing;
      ctx.fillStyle = m >= 5 ? '#ef4444' : m >= 1 ? '#22c55e' : '#3b82f6';
      ctx.beginPath(); ctx.roundRect(sx, slotY, colSpacing - 4, 40, 8); ctx.fill();
      ctx.fillStyle = '#fff'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';
      ctx.fillText(`${m}x`, sx + (colSpacing - 4) / 2, slotY + 25);
    });
    ballsRef.current.forEach(ball => {
      ctx.beginPath(); ctx.arc(ball.x, ball.y, BALL_RADIUS, 0, Math.PI * 2);
      ctx.fillStyle = '#fbbf24'; ctx.shadowBlur = 15; ctx.shadowColor = '#f59e0b'; ctx.fill(); ctx.shadowBlur = 0;
    });
  };

  const handleBallLand = (ball: Ball) => {
    const slotIdx = Math.min(Math.max(ball.col, 0), MULTIPLIERS.length - 1);
    const multiplier = MULTIPLIERS[slotIdx];
    const winAmount = ball.bet * multiplier;
    updateBalance(winAmount, 'WIN', `Plinko ${multiplier}x`);
    playSound(multiplier >= 1 ? 'win' : 'click');
    const rid = Math.random().toString(36).substr(2, 5);
    setFloatingResults(prev => [...prev, { id: rid, mult: multiplier, amount: winAmount }]);
    // FIX: Reduced timeout to 1 second as requested
    setTimeout(() => { setFloatingResults(prev => prev.filter(res => res.id !== rid)); }, 1000);
    addGameHistory('Plinko', ball.bet, winAmount, `Hit ${multiplier}x`);
  };

  const dropBall = () => {
    if (userBalance < betAmount) { playSound('loss'); return; }
    updateBalance(-betAmount, 'BET', 'Plinko Stake');
    const startCoords = getPinCoords(0, 0);
    ballsRef.current.push({
      id: Math.random().toString(36).substr(2, 9), x: CANVAS_WIDTH / 2, y: 30, row: 0, col: 0, bet: betAmount,
      status: 'DROPPING', targetX: startCoords.x, targetY: startCoords.y, progress: 0, startPos: { x: CANVAS_WIDTH / 2, y: 30 }
    });
    playSound('click');
  };

  return (
    <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white relative overflow-hidden">
      {floatingResults.map(res => (
          <div key={res.id} className="fixed top-[40%] left-1/2 -translate-x-1/2 z-[100] w-full px-10 pointer-events-none animate-in fade-in zoom-in duration-300">
               <div className={`py-4 px-8 rounded-full border-4 shadow-2xl flex items-center justify-center gap-6 backdrop-blur-xl ${res.mult >= 1 ? 'bg-green-600/90 border-green-400' : 'bg-red-600/90 border-red-400'}`}>
                   <span className="font-black italic text-3xl">{res.mult}x</span>
                   <div className="w-[2px] h-10 bg-white/20"></div>
                   <span className="font-black text-4xl">₹{res.amount.toFixed(2)}</span>
               </div>
          </div>
      ))}
      <div className="p-4 flex justify-between items-center bg-[#111827]/95 backdrop-blur-xl border-b border-white/5 z-50">
        <button onClick={onBack} className="p-2.5 bg-slate-800 rounded-2xl active:scale-90"><ArrowLeft size={20}/></button>
        <h1 className="text-xl font-black italic gold-text tracking-widest uppercase">PLINKO</h1>
        <div className="flex gap-2">
            <button onClick={() => setShowRules(true)} className="p-2.5 bg-slate-800 rounded-xl active:scale-90"><HelpCircle size={20}/></button>
            <div className="flex items-center gap-2 bg-black/50 px-4 py-2 rounded-2xl border border-yellow-500/20">
              <Wallet size={14} className="text-yellow-500" />
              <span className="text-sm font-black text-yellow-500">₹{userBalance.toFixed(2)}</span>
            </div>
        </div>
      </div>
      <div className="flex-1 flex flex-col items-center justify-center p-4 relative">
        <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="max-w-full rounded-[2.5rem] bg-[#111827]/60 border border-white/10 shadow-2xl" />
      </div>
      <div className="bg-[#111827] border-t border-white/5 p-6 pb-12 z-50">
        <div className="flex justify-between items-end mb-6">
            <div className="text-2xl font-black italic">₹{betAmount}</div>
            <button onClick={() => setMuted(toggleMute())} className="p-3 bg-slate-800 rounded-2xl">{muted ? <VolumeX size={22}/> : <Volume2 size={22}/>}</button>
        </div>
        <div className="grid grid-cols-4 gap-3 mb-8">
            {[10, 50, 100, 500].map(amt => <button key={amt} onClick={() => setBetAmount(amt)} className={`py-4 rounded-2xl font-black text-xs border transition-all ${betAmount === amt ? 'bg-yellow-500 text-slate-950 border-white' : 'bg-slate-800/40 border-white/5 text-slate-400'}`}>₹{amt}</button>)}
        </div>
        <button onClick={dropBall} className="w-full py-6 rounded-[2rem] bg-gradient-to-r from-yellow-400 via-orange-500 to-yellow-600 text-slate-950 font-black uppercase tracking-[0.4em] shadow-2xl active:scale-95 flex items-center justify-center gap-4 text-lg border-t-2 border-white/20"><PlayCircle size={28}/> DROP BALL</button>
      </div>
      {showRules && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/90">
              <div className="bg-slate-900 border-2 border-white/10 w-full max-w-sm p-10 rounded-[3.5rem] shadow-2xl">
                   <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-4">
                       <h2 className="text-2xl font-black text-blue-500 italic uppercase">RULES</h2>
                       <button onClick={() => setShowRules(false)} className="p-2 bg-slate-800 rounded-full"><X size={20}/></button>
                   </div>
                   <div className="space-y-4 text-sm text-slate-300 leading-relaxed">
                       <p>1. Set your stake and drop the ball.</p>
                       <p>2. The multiplier slot the ball lands in determines your win.</p>
                       <p>3. High multipliers are on the edges.</p>
                   </div>
              </div>
          </div>
      )}
    </div>
  );
};
export default Plinko;

import React, { useEffect, useState } from 'react';
import { GameResult } from '../types';
import { X, Trophy, Frown, Sparkles, Star } from 'lucide-react';

const Overlay: React.FC<{ children: React.ReactNode; visible: boolean }> = ({ children, visible }) => (
    <div className={`fixed inset-0 z-[100] flex items-center justify-center pointer-events-none ${visible ? 'opacity-100' : 'opacity-0'} transition-opacity duration-300`}>
        <div className="absolute inset-0 bg-black/90 backdrop-blur-md"></div>
        <div className={`relative pointer-events-auto transform transition-all duration-500 ${visible ? 'scale-100 translate-y-0' : 'scale-50 translate-y-10'}`}>{children}</div>
    </div>
);

const GameResultPopup: React.FC<{ result: GameResult | null; onClose: () => void; }> = ({ result, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => { 
        if (result) { 
            setVisible(true); 
            // Plinko result popup is handled specially inside the game, but for general results we keep it consistent
            // Plinko specifically requested 1 second.
            const duration = result.game === 'Plinko' ? 1000 : 4000;
            const t = setTimeout(handleClose, duration); 
            return () => clearTimeout(t); 
        } 
    }, [result]);

    const handleClose = () => { 
        setVisible(false); 
        setTimeout(onClose, 300); 
    };

    if (!result && !visible) return null;

    // WINNING STATE - No X button as per request
    if (result?.win) {
        return (
            <Overlay visible={visible}>
                <div className="w-[85vw] max-w-sm bg-gradient-to-b from-[#fcd34d] to-[#d97706] rounded-[2.5rem] p-1 shadow-[0_0_100px_rgba(217,119,6,0.6)] relative">
                    <div className="bg-[#111827] rounded-[2.4rem] p-8 text-center border border-white/10 overflow-hidden relative">
                        <div className="absolute top-0 left-0 w-full h-full pointer-events-none opacity-20">
                            <Sparkles className="absolute top-4 left-4 text-yellow-400 animate-pulse" size={24}/>
                            <Sparkles className="absolute bottom-10 right-4 text-yellow-400 animate-bounce" size={20}/>
                        </div>

                        <div className="flex justify-center mb-6">
                            <div className="bg-yellow-500/20 p-5 rounded-full border border-yellow-500/30 relative">
                                <Trophy size={64} className="text-yellow-500 fill-yellow-500/10 drop-shadow-[0_0_20px_rgba(234,179,8,0.5)]" />
                                <div className="absolute -top-1 -right-1 bg-white rounded-full p-1"><Star size={16} className="text-yellow-600 fill-yellow-600"/></div>
                            </div>
                        </div>

                        <h2 className="text-3xl font-black italic tracking-tighter gold-text uppercase mb-1">Congratulations</h2>
                        <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.4em] mb-8">Mission Accomplished</p>

                        <div className="space-y-6">
                            <div className="bg-[#0a0f1d] py-6 rounded-3xl border border-slate-800 shadow-inner">
                                <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mb-1">Earnings Captured</p>
                                <div className="text-6xl font-black text-yellow-400 drop-shadow-lg tracking-tighter italic">
                                    ₹{result.amount.toFixed(2)}
                                </div>
                            </div>
                        </div>

                        <button 
                            onClick={handleClose}
                            className="mt-10 w-full py-4 bg-gradient-to-r from-yellow-500 to-orange-600 rounded-2xl font-black uppercase text-sm text-black shadow-2xl active:scale-95 transition-all border-t-2 border-white/30"
                        >
                            CLAIM ASSETS
                        </button>
                    </div>
                </div>
            </Overlay>
        );
    }

    // LOSS STATE - Includes X button near lobby action/top right
    return (
        <Overlay visible={visible}>
            <div className="w-[85vw] max-w-sm bg-[#1e293b] rounded-[3rem] p-10 text-center border-t-4 border-slate-600 shadow-[0_30px_100px_rgba(0,0,0,1)] relative">
                <button onClick={handleClose} className="absolute top-6 right-6 p-2 bg-slate-800 rounded-full border border-white/5 text-slate-400 active:scale-90"><X size={18}/></button>

                <div className="flex justify-center mb-8">
                    <div className="bg-slate-800/80 p-6 rounded-full border border-slate-600 shadow-inner">
                        <Frown size={56} className="text-slate-500" />
                    </div>
                </div>

                <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-3 italic">Defeat</h2>
                <p className="text-sm text-slate-400 font-medium mb-10 px-4 leading-relaxed">The underworld is unpredictable. Regroup and stake again to reclaim your territory.</p>

                <div className="bg-[#0f172a] p-5 rounded-3xl border border-slate-800 mb-10 flex justify-between items-center shadow-inner">
                    <span className="text-[10px] text-slate-600 font-black uppercase tracking-widest">Stake amount lost</span>
                    <span className="text-2xl font-black text-slate-400 italic">₹{result?.amount.toFixed(2)}</span>
                </div>

                <button 
                    onClick={handleClose}
                    className="w-full py-5 bg-slate-800 hover:bg-slate-700 border border-slate-700 text-white rounded-[2rem] font-black uppercase text-sm shadow-xl active:scale-95 transition-all"
                >
                    Return to Lobby
                </button>
            </div>
        </Overlay>
    );
};

export default GameResultPopup;

import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, History as HistoryIcon, X, Wallet, Volume2, VolumeX, HelpCircle, Clock, ChevronRight, AlertCircle } from 'lucide-react';
import { WinGoGameState, GameResult, GameHistoryItem, WinGoHistory } from '../types';
import { subscribeToWinGo, updateBalance, stopAllSounds, toggleMute, getMuteStatus, playSound, shouldForceLoss, getGameHistory, addGameHistory } from '../services/mockFirebase';

const WinGo: React.FC<{ onBack: () => void; userBalance: number; onResult: (r: GameResult) => void; setView: (v: any) => void; }> = ({ onBack, userBalance, onResult, setView }) => {
  const [gameState, setGameState] = useState<WinGoGameState | null>(null);
  const [activeTab, setActiveTab] = useState<'History' | 'MyBets'>('History');
  const [betDrawerOpen, setBetDrawerOpen] = useState(false);
  const [selectedBetTarget, setSelectedBetTarget] = useState<string | null>(null);
  const [betMoney, setBetMoney] = useState(1);
  const [betMultiplier, setBetMultiplier] = useState(1);
  const [muted, setMuted] = useState(getMuteStatus());
  const [showBalanceError, setShowBalanceError] = useState(false);
  const [pendingBets, setPendingBets] = useState<{target: string; amount: number; period: number}[]>([]);
  const [myHistory, setMyHistory] = useState<GameHistoryItem[]>([]);

  const isMounted = useRef(true);

  useEffect(() => {
    isMounted.current = true;
    const unsubHistory = getGameHistory('WinGo', (data) => {
        if(isMounted.current) setMyHistory(data);
    });
    return () => { isMounted.current = false; stopAllSounds(); unsubHistory(); };
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToWinGo((state) => {
        if (!isMounted.current) return;

        // Pre-generate fake history if empty to ensure table is always populated
        let finalState = { ...state };
        if (!finalState.history || finalState.history.length === 0) {
            const fakeHistory: WinGoHistory[] = [];
            for (let i = 0; i < 15; i++) {
                const n = Math.floor(Math.random() * 10);
                fakeHistory.push({
                    period: (state.period - 1 - i).toString(),
                    number: n,
                    bigSmall: n >= 5 ? 'Big' : 'Small',
                    color: n === 0 || n === 5 ? 'Violet' : [1, 3, 7, 9].includes(n) ? 'Green' : 'Red'
                });
            }
            finalState.history = fakeHistory;
        }

        setGameState(finalState);

        if (finalState.timeLeft <= 5 && finalState.timeLeft > 0 && finalState.status === 'BETTING') {
            playSound('wingo_tick');
        }

        if (finalState.timeLeft === 30 && finalState.lastResult) {
            playSound('wingo_draw');
            const finishedPeriod = finalState.lastResult.period;
            const currentRoundBets = pendingBets.filter(b => b.period.toString() === finishedPeriod);

            if (currentRoundBets.length > 0) {
                let totalWin = 0; let totalBet = 0; let hasWin = false;
                const num = finalState.lastResult.number;
                const bS = finalState.lastResult.bigSmall;

                currentRoundBets.forEach(bet => {
                    totalBet += bet.amount;
                    let betWin = false, mult = 0;
                    const forcedLoss = shouldForceLoss(bet.amount, userBalance);

                    if (!forcedLoss) {
                        if (bet.target === 'Green' && [1,3,5,7,9].includes(num)) { betWin = true; mult = num===5?1.5:2; }
                        else if (bet.target === 'Red' && [0,2,4,6,8].includes(num)) { betWin = true; mult = num===0?1.5:2; }
                        else if (bet.target === 'Violet' && [0,5].includes(num)) { betWin = true; mult = 4.5; }
                        else if (bet.target === 'Big' && bS === 'Big') { betWin = true; mult = 2; }
                        else if (bet.target === 'Small' && bS === 'Small') { betWin = true; mult = 2; }
                        else if (bet.target === num.toString()) { betWin = true; mult = 9; }
                    }

                    if (betWin) { hasWin = true; totalWin += bet.amount * mult; }
                    addGameHistory('WinGo', bet.amount, betWin ? bet.amount * mult : 0, `P:${finishedPeriod} | Target:${bet.target} | Result:${num}`);
                });

                if (totalWin > 0) updateBalance(totalWin, 'WIN', 'WinGo Win');
                onResult({ 
                    win: hasWin, 
                    amount: hasWin ? totalWin : totalBet, 
                    game: 'WinGo', 
                    period: finishedPeriod, 
                    resultDetails: [
                        { label: 'Number', value: num.toString(), color: num%2===0?'bg-red-500':'bg-green-500' },
                        { label: 'Size', value: bS, color: bS==='Big'?'bg-yellow-500':'bg-blue-500' }
                    ] 
                });
                setPendingBets(prev => prev.filter(b => b.period.toString() !== finishedPeriod));
            }
        }
    });
    return () => unsubscribe();
  }, [pendingBets, userBalance]);

  const confirmBet = () => {
      const total = betMoney * betMultiplier;
      if (total > userBalance) { 
          setShowBalanceError(true); 
          setTimeout(() => setShowBalanceError(false), 3000); 
          return; 
      }
      updateBalance(-total, 'BET', `WinGo Stake: ${selectedBetTarget}`);
      setBetDrawerOpen(false);
      setPendingBets(prev => [...prev, { target: selectedBetTarget!, amount: total, period: gameState!.period }]);
      playSound('click');
  };

  if (!gameState) return <div className="min-h-screen bg-[#0f172a] flex items-center justify-center text-white italic font-black uppercase tracking-widest">Entering Arena...</div>;

  const isBetLocked = gameState.timeLeft <= 5;
  const getBallColor = (n: number) => n===0?'bg-purple-500':n===5?'bg-purple-500':[1,3,7,9].includes(n)?'bg-green-500':'bg-red-500';

  return (
    <div className="bg-[#0f172a] min-h-screen pb-24 relative font-sans select-none overflow-x-hidden">
      {/* Insufficient Balance Popup */}
      {showBalanceError && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[200] bg-red-600 px-6 py-3 rounded-full shadow-2xl flex items-center gap-3 border border-red-400 animate-in slide-in-from-top-4">
              <AlertCircle className="text-white" size={20}/>
              <span className="font-black text-xs uppercase tracking-widest">Insufficient Balance!</span>
          </div>
      )}

      <div className="bg-[#1e293b] p-4 sticky top-0 z-20 flex justify-between items-center border-b border-white/5 shadow-xl">
        <div className="flex items-center gap-3">
            <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20} /></button>
            <h1 className="text-lg font-black italic gold-text uppercase">WINGO 30S</h1>
        </div>
        <button onClick={()=>{setMuted(toggleMute())}} className="p-2 bg-slate-800 rounded-xl">
            {muted?<VolumeX size={20} className="text-slate-400"/>:<Volume2 size={20} className="text-slate-400"/>}
        </button>
      </div>

      <div className="bg-[#1e293b] m-4 p-5 rounded-[2rem] flex justify-between items-center shadow-xl border border-white/5">
          <div className="flex items-center gap-4">
              <div className="bg-yellow-500 p-3 rounded-2xl text-slate-900 shadow-lg"><Wallet size={24} /></div>
              <div>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Balance</p>
                  <h2 className="text-2xl font-black text-white italic">₹{userBalance.toFixed(2)}</h2>
              </div>
          </div>
          <button onClick={() => setView('DEPOSIT')} className="px-5 py-2 bg-blue-600 rounded-xl text-[10px] font-black uppercase text-white shadow-lg active:scale-95 transition-all">Deposit</button>
      </div>

      <div className="p-6 bg-gradient-to-br from-blue-900 to-[#0f172a] m-4 rounded-[2.5rem] flex flex-col items-center border border-white/5 shadow-2xl relative overflow-hidden">
         <div className="absolute top-0 right-0 p-20 bg-blue-500/10 rounded-full blur-3xl -mr-10 -mt-10"></div>
         <div className="text-center w-full relative z-10">
            <div className="text-[10px] text-blue-200 uppercase font-black tracking-[0.3em] mb-4">Period: {gameState.period}</div>
            <div className={`text-6xl font-black font-mono tracking-tighter flex justify-center gap-2 ${isBetLocked ? 'text-red-500 animate-pulse' : 'text-white'}`}>
                <span className="bg-black/40 px-3 py-1 rounded-xl">0</span>
                <span className="bg-black/40 px-3 py-1 rounded-xl">0</span>
                <span className="text-blue-500">:</span>
