                    <button onClick={() => handleTargetClick('Tie')} disabled={gameState.status !== 'BETTING' || gameState.timeLeft <= 3} className={`h-32 rounded-3xl border-b-[10px] transition-all active:scale-95 flex flex-col items-center justify-center ${gameState.status === 'BETTING' ? 'bg-green-950/40 border-green-700 shadow-xl' : 'bg-slate-900 border-slate-950 opacity-40 grayscale'}`}>
                        <span className="text-2xl font-black italic text-green-500 drop-shadow-lg">TIE</span>
                        <span className="text-[10px] font-black text-slate-500 mt-1 uppercase">9.0X</span>
                        {myBets.filter(b=>b.target==='Tie').length > 0 && <div className="mt-2 bg-yellow-500 text-black px-4 py-1 rounded-full text-[10px] font-black animate-in zoom-in shadow-xl">₹{myBets.filter(b=>b.target==='Tie').reduce((a,b)=>a+b.amount,0)}</div>}
                    </button>
                    <button onClick={() => handleTargetClick('T')} disabled={gameState.status !== 'BETTING' || gameState.timeLeft <= 3} className={`h-32 rounded-3xl border-b-[10px] transition-all active:scale-95 flex flex-col items-center justify-center ${gameState.status === 'BETTING' ? 'bg-orange-950/40 border-orange-700 shadow-xl' : 'bg-slate-900 border-slate-950 opacity-40 grayscale'}`}>
                        <span className="text-2xl font-black italic text-orange-500 drop-shadow-lg">TIGER</span>
                        <span className="text-[10px] font-black text-slate-500 mt-1 uppercase">2.0X</span>
                        {myBets.filter(b=>b.target==='T').length > 0 && <div className="mt-2 bg-yellow-500 text-black px-4 py-1 rounded-full text-[10px] font-black animate-in zoom-in shadow-xl">₹{myBets.filter(b=>b.target==='T').reduce((a,b)=>a+b.amount,0)}</div>}
                    </button>
                </div>

                <div className="flex justify-between items-center px-6 py-4 rounded-2xl bg-black/40 border border-white/5 mt-4">
                   <div className="flex items-center gap-2 text-zinc-500"><History size={16}/><span className="text-[10px] font-black uppercase tracking-widest">Active Stakes</span></div>
                   <div className="text-right"><span className="text-[10px] text-zinc-600 block uppercase font-black">Subtotal</span><span className="text-lg font-black text-white italic">₹{currentTotalStaked.toFixed(2)}</span></div>
                </div>
            </div>

            {confirmDrawerOpen && (
                <div className="fixed inset-0 z-[200] flex items-end justify-center bg-black/85 backdrop-blur-md">
                    <div className="bg-[#111] w-full max-w-md rounded-t-[3.5rem] p-10 border-t-2 border-yellow-500/40 animate-in slide-in-from-bottom duration-300">
                        <div className="flex justify-between items-center mb-8">
                             <div>
                                <p className="text-[10px] text-zinc-500 font-black uppercase tracking-[0.2em] mb-1">Target Arena</p>
