export const getGameHistory = (gameName: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) return () => {};
    const historyRef = ref(db, `game_history/${currentUser.uid}`);
    return onValue(historyRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            let list = Object.entries(val).map(([id, item]: [string, any]) => ({ id, ...item }));
            list.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
            if (gameName !== 'ALL') list = list.filter(i => i.game === gameName);
            cb(list);
        } else cb([]);
    });
};

