const calculateReferralStats = (myCode: string) => {
    if (!myCode) return;
    referralStats.code = myCode;
    referralStats.link = `${window.location.origin}/#/register?inviteCode=${myCode}`;

    // Fetch subordinates and calculate stats
    const usersRef = ref(db, 'users');
    onValue(usersRef, (snapshot) => {
        const users = snapshot.val();
        if (users) {
            const subordinates = Object.values(users).filter((u: any) => u.invitedBy === myCode);
            referralStats.directSubordinates = subordinates.length;
            referralStats.teamSubordinates = subordinates.length; // Simplified
            // Add explicit number typing for reduce accumulator to fix 'unknown' type errors (Fix for Line 187/188)
            referralStats.totalDepositAmount = subordinates.reduce((acc: number, curr: any) => acc + (curr.totalDeposit || 0), 0);
            // Add explicit number typing for reduce accumulator to fix 'unknown' type errors (Fix for Line 188)
            referralStats.totalBetAmount = subordinates.reduce((acc: number, curr: any) => acc + (curr.totalBet || 0), 0);

            // Commission calculation based on network turnover (0.6% example)
            // Add explicit number typing for reduce accumulator to fix 'unknown' type errors (Fix for Line 191)
            referralStats.totalCommission = subordinates.reduce((acc: number, curr: any) => acc + ((curr.totalDeposit || 0) * 0.1), 0);
        }
    });
};

