let wingoState: WinGoGameState = { timeLeft: 30, period: 202511261000, status: 'BETTING', history: [], lastResult: null };
const wingoSubs: Function[] = [];

export const startGlobalEngines = () => {
    setInterval(() => {
        wingoState.timeLeft -= 1;
        if (wingoState.timeLeft <= 0) {
            const num = Math.floor(Math.random() * 10);
            let color: 'Red'|'Green'|'Violet' = 'Red';
            if (num === 0 || num === 5) color = 'Violet';
            else if ([1,3,7,9].includes(num)) color = 'Green';
            const res: WinGoHistory = { period: wingoState.period.toString(), number: num, bigSmall: num >= 5 ? 'Big' : 'Small', color };
            wingoState.lastResult = res;
            wingoState.history = [res, ...wingoState.history].slice(0, 50);
            wingoState.period += 1;
            wingoState.timeLeft = 30;
        }
        wingoSubs.forEach(cb => cb({ ...wingoState }));
    }, 1000);
};

export const subscribeToWinGo = (cb: (state: WinGoGameState) => void) => { wingoSubs.push(cb); cb({ ...wingoState }); return () => { wingoSubs.splice(wingoSubs.indexOf(cb), 1); }; };

export const subscribeToAviator = (cb: (state: AviatorState) => void) => {
    let state: AviatorState = { phase: 'WAITING', multiplier: 1.0, timeLeft: 10, history: [], crashPoint: 0 };
    const interval = setInterval(() => {
        if (state.phase === 'WAITING') {
            state.timeLeft -= 1;
            if (state.timeLeft <= 0) { state.phase = 'FLYING'; state.multiplier = 1.0; state.startTime = Date.now(); state.crashPoint = 1.2 + Math.random() * 5.0; }
        } else if (state.phase === 'FLYING') {
            const elapsed = (Date.now() - (state.startTime || Date.now())) / 1000;
            state.multiplier = 1 + (elapsed * 0.1) + (Math.pow(elapsed, 2) * 0.05);
            if (state.multiplier >= state.crashPoint) {
                state.phase = 'CRASHED'; state.multiplier = state.crashPoint; state.history = [state.crashPoint, ...state.history].slice(0, 15);
                setTimeout(() => { state.phase = 'WAITING'; state.timeLeft = 10; state.multiplier = 1.0; }, 3000);
            }
        }
        cb({ ...state });
    }, 100);
    return () => clearInterval(interval);
};

export const subscribeToDragonTiger = (cb: (state: DragonTigerState) => void) => {
    let state: DragonTigerState = { status: 'BETTING', timeLeft: 15, period: '20251128001', dragonCard: null, tigerCard: null, history: [] };
    const interval = setInterval(() => {
        state.timeLeft -= 1;
        if (state.timeLeft <= 0) {
            if (state.status === 'BETTING') { state.status = 'LOCKED'; state.timeLeft = 3; }
            else if (state.status === 'LOCKED') {
                state.status = 'RESULT';
                state.dragonCard = Math.floor(Math.random() * 13) + 1;
                state.tigerCard = Math.floor(Math.random() * 13) + 1;
                const res: "D" | "T" | "Tie" = state.dragonCard > state.tigerCard ? 'D' : state.tigerCard > state.dragonCard ? 'T' : 'Tie';
                state.history = [res, ...state.history].slice(0, 20);
                state.timeLeft = 5;
            } else {
                state.status = 'BETTING'; state.timeLeft = 15;
                state.period = (parseInt(state.period) + 1).toString();
                state.dragonCard = null; state.tigerCard = null;
            }
        }
        cb({ ...state });
    }, 1000);
    return () => clearInterval(interval);
};

