import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Coins, Volume2, VolumeX, RotateCcw } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus } from '../services/mockFirebase';
import { GameResult } from '../types';

interface DogProps {
    onBack: () => void;
    userBalance: number;
    onResult: (result: GameResult) => void;
}

type Difficulty = 'EASY' | 'MEDIUM' | 'HARD' | 'HARDCORE';

const MULTIPLIERS: Record<Difficulty, number[]> = {
    EASY: [1.3, 1.7, 2.3, 3.2, 4.4, 6.2, 8.7, 12.5, 18.3, 26.9, 40.0, 60.0, 90.0, 135.0, 205.0],
    MEDIUM: [1.4, 2.2, 3.5, 5.5, 9.1, 15.3, 26.8, 48.7, 91.3, 175.0, 350.0, 700.0, 1400.0, 2800.0, 5600.0],
    HARD: [2.9, 9.1, 29.4, 99.0, 345.0, 1250.0, 4500.0, 16000.0, 58000.0, 210000.0, 750000.0, 2500000.0, 9000000.0, 30000000.0, 99000000.0],
    HARDCORE: [4.9, 24.5, 122.5, 612.5, 3062.5, 15312.5, 76562.5, 382812.5, 1914062.5, 9570312.5, 47851562.5, 239257812.5, 999999999.0, 999999999.0, 999999999.0]
};

const CAR_IMAGES = ['🚕', '🚓', '🚚', '🚑', '🚒', '🚐'];

const DogRoad: React.FC<DogProps> = ({ onBack, userBalance, onResult }) => {
    const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'CRASHING' | 'CRASHED' | 'WON'>('IDLE');
    const [currentLane, setCurrentLane] = useState(-1);
    const [betAmount, setBetAmount] = useState(10);
    const [difficulty, setDifficulty] = useState<Difficulty>('MEDIUM');
    const [muted, setMuted] = useState(getMuteStatus());
    const [crashLane, setCrashLane] = useState<number | null>(null);
    const [carType, setCarType] = useState('🚕');
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; stopAllSounds(); };
    }, []);

    const startGame = () => {
        if (betAmount > userBalance) { alert("Insufficient Balance!"); return; }
        playSound('click');
        updateBalance(-betAmount, 'BET', 'Dog Road');
        setGameState('PLAYING');
        setCurrentLane(-1);
        setCrashLane(null);
    };

    const nextStep = () => {
        if (gameState !== 'PLAYING') return;
        playSound('click');
        let failChance = difficulty === 'EASY' ? 0.15 : difficulty === 'MEDIUM' ? 0.25 : difficulty === 'HARD' ? 0.45 : 0.65;
        if (Math.random() < failChance) initiateCrash();
        else handleSuccess();
    };

    const handleSuccess = () => {
        playSound('win');
        setCurrentLane(prev => prev + 1);
        if (currentLane + 1 >= MULTIPLIERS[difficulty].length - 1) cashOut();
    };

    const initiateCrash = () => {
        const nextLane = currentLane + 1;
        setCrashLane(nextLane);
        setCarType(CAR_IMAGES[Math.floor(Math.random() * CAR_IMAGES.length)]);
        setGameState('CRASHING'); 
        playSound('loss'); 
        setTimeout(() => {
            if (!isMounted.current) return;
            setGameState('CRASHED');
            addGameHistory('Dog Road', betAmount, 0, `Crashed at Lane ${nextLane}`);
            onResult({ win: false, amount: betAmount, game: 'Dog Road' });
        }, 800);
    };

    const cashOut = () => {
        if (currentLane === -1) { updateBalance(betAmount, 'GIFT', 'Stake Returned'); setGameState('IDLE'); return; }
        const mult = MULTIPLIERS[difficulty][currentLane];
        const winAmount = betAmount * mult; 
        updateBalance(winAmount, 'WIN', 'Dog Road Win');
        addGameHistory('Dog Road', betAmount, winAmount, `Cashed out ${mult}x`);
        playSound('win');
        setGameState('WON');
        onResult({ win: true, amount: winAmount, game: 'Dog Road', resultDetails: [{ label: 'Victory', value: `${mult}x` }] });
    };

    const currentMultiplier = currentLane === -1 ? 1.0 : MULTIPLIERS[difficulty][currentLane];
    const potentialWin = (betAmount * currentMultiplier).toFixed(2);
    let translateX = currentLane > -1 ? -(currentLane + 1) * 25 + 25 : 0;

    return (
        <div className="bg-[#1a1c20] min-h-screen flex flex-col font-sans text-white overflow-hidden select-none">
            <div className="bg-[#24262b] p-3 flex items-center justify-between border-b border-gray-800 z-20 shadow-xl">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} disabled={gameState === 'PLAYING'}><ArrowLeft className="text-gray-400" /></button>
                    <span className="font-black text-xl italic gold-text">DOG <span className="text-orange-500">ROAD</span></span>
                </div>
                <div className="flex items-center gap-3">
                    <div className="bg-black/30 px-3 py-1 rounded-full border border-gray-700 text-yellow-500 text-sm font-mono">₹{userBalance.toFixed(2)}</div>
                    <button onClick={() => setMuted(toggleMute())}>{muted ? <VolumeX size={20}/> : <Volume2 size={20}/>}</button>
                </div>
            </div>

            <div className="flex-1 relative overflow-hidden bg-[#2b2e33]">
                <div className="absolute inset-y-0 left-0 flex items-center transition-transform duration-500 ease-in-out" style={{ transform: `translateX(${translateX + 10}vw)`, width: `${(MULTIPLIERS[difficulty].length + 1) * 25}vw` }}>
                    <div className="w-[25vw] h-full flex-shrink-0 bg-[#3a4042] border-r-4 border-gray-500 relative flex flex-col justify-center items-center z-10">
                        <div className="w-20 h-20 bg-orange-800/20 rounded-full flex items-center justify-center mb-8 border-2 border-orange-900/50 shadow-inner text-4xl">🏁</div>
                        {currentLane === -1 && gameState !== 'CRASHED' && gameState !== 'CRASHING' && (
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20"><img src="https://cdn-icons-png.flaticon.com/512/616/616554.png" className="w-16 h-16 animate-bounce" /></div>
                        )}
                    </div>
                    {MULTIPLIERS[difficulty].map((mult, index) => (
                        <div key={index} className="w-[25vw] h-full flex-shrink-0 relative border-r-2 border-dashed border-gray-600/50 flex items-center justify-center">
                            <div className={`relative w-20 h-20 rounded-full flex items-center justify-center border-4 border-gray-700 ${currentLane >= index ? 'opacity-50' : ''}`}>
                                <div className="absolute inset-2 rounded-full bg-[#25282c] flex items-center justify-center text-gray-400 font-black text-xl italic">{mult}x</div>
                            </div>
                            {currentLane === index && gameState !== 'CRASHED' && gameState !== 'CRASHING' && (
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20"><img src="https://cdn-icons-png.flaticon.com/512/616/616554.png" className="w-16 h-16 animate-bounce" /></div>
                            )}
                            {crashLane === index && (
                                <div className={`absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-30 transition-all duration-700 ${gameState==='CRASHING'?'translate-y-0 opacity-100':'-translate-y-[200px] opacity-0'}`}><div className="text-6xl transform scale-y-[-1]">{carType}</div></div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-[#24262b] p-4 border-t border-gray-800 z-20">
                {gameState === 'IDLE' || gameState === 'CRASHED' || gameState === 'WON' ? (
                    <div className="space-y-4">
                         <div className="flex bg-[#1a1c20] p-1 rounded-lg">
                            {(['EASY', 'MEDIUM', 'HARD', 'HARDCORE'] as Difficulty[]).map(d => <button key={d} onClick={() => setDifficulty(d)} className={`flex-1 py-2 rounded-md text-xs font-bold ${difficulty === d ? 'bg-gray-600 border border-white/20' : 'text-gray-500'}`}>{d}</button>)}
                        </div>
                        <div className="flex gap-4">
                            <div className="flex-1 bg-[#1a1c20] rounded-lg p-3 border border-gray-700">
                                <label className="text-[10px] text-gray-500 font-bold uppercase block mb-1">Bet Amount</label>
                                <input type="number" value={betAmount} onChange={e => setBetAmount(Number(e.target.value))} className="bg-transparent outline-none text-white font-bold text-lg w-full" />
                            </div>
                            <button onClick={startGame} className="flex-[2] bg-green-500 text-black font-black text-xl rounded-lg shadow-[0_4px_0_rgb(21,128,61)] active:translate-y-1 transition-all uppercase tracking-wide">Play</button>
                        </div>
                    </div>
                ) : gameState === 'PLAYING' ? (
                    <div className="flex gap-4 animate-in slide-in-from-bottom">
                         <button onClick={cashOut} className="flex-1 bg-orange-500 text-black font-black text-lg rounded-lg shadow-[0_4px_0_rgb(194,65,12)] active:translate-y-1 transition-all uppercase py-3 flex flex-col items-center">
                            <span>{currentLane === -1 ? 'RETURN' : 'COLLECT'}</span>
                            {currentLane > -1 && <span className="text-xs font-medium">₹{potentialWin}</span>}
                         </button>
                         <button onClick={nextStep} className="flex-[2] bg-green-500 text-black font-black text-lg rounded-lg shadow-[0_4px_0_rgb(21,128,61)] active:translate-y-1 transition-all uppercase">GO</button>
                    </div>
                ) : null}
            </div>
            <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
        </div>
    );
};
export default DogRoad;

