const calculateReferralStats = (myCode: string) => {
    if (!myCode) return;
    referralStats.code = myCode;
    referralStats.link = `${window.location.origin}/#/register?inviteCode=${myCode}`;

    // Fetch subordinates and calculate stats
    const usersRef = ref(db, 'users');
    onValue(usersRef, (snapshot) => {
        const users = snapshot.val() as any;
        if (users) {
            const subordinates = Object.values(users).filter((u: any) => u.invitedBy === myCode);
            referralStats.directSubordinates = subordinates.length;
            referralStats.teamSubordinates = subordinates.length; // Simplified
            referralStats.totalDepositAmount = subordinates.reduce((acc: number, curr: any) => acc + (curr.totalDeposit || 0), 0) as number;
            referralStats.totalBetAmount = subordinates.reduce((acc: number, curr: any) => acc + (curr.totalBet || 0), 0) as number;
            referralStats.totalCommission = subordinates.reduce((acc: number, curr: any) => acc + ((curr.totalDeposit || 0) * 0.1), 0) as number;
        }
    });
};

export const getSubordinates = (cb: (data: SubordinateItem[]) => void) => {
    if (!currentUser) return () => {};
    const usersRef = ref(db, 'users');
    return onValue(usersRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const subs = Object.entries(val)
                .filter(([uid, u]: [string, any]) => u.invitedBy === currentUser?.inviteCode)
                .map(([uid, u]: [string, any]) => ({
                    id: uid, uid: uid, level: 1,
                    depositAmount: u.totalDeposit || 0,
                    betAmount: u.totalBet || 0,
                    commission: (u.totalDeposit || 0) * 0.1,
                    date: u.createdAt || '2024-01-01'
                }));
            cb(subs);
        } else cb([]);
    });
};

export const getCommissions = (cb: (data: CommissionItem[]) => void) => {
    if (!currentUser) return () => {};
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    return onValue(txRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val)
                .filter(([id, item]: [string, any]) => item.type === 'COMMISSION')
                .map(([id, item]: [string, any]) => ({
                    id, fromUid: 'System', amount: item.amount, date: item.date, type: item.desc || 'Referral Commission'
                }));
            cb(list);
        } else cb([]);
    });
};

export const claimCommission = async () => {
    if (!currentUser || referralStats.totalCommission <= 0) return { success: false, message: 'No assets to claim' };
    const amount = referralStats.totalCommission;
    await updateBalance(amount, 'COMMISSION', 'Claimed Agency Rewards');
    return { success: true, message: amount.toFixed(2) };
};

export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser) return 0;

    const userSnapshot = await get(ref(db, `users/${currentUser.uid}`));
    const userData = userSnapshot.val();
    const usedCodes = userData.usedGiftCodes || [];

    if (usedCodes.includes(code)) return -1;

    // xi code added secretly
    if (code === 'xi' || code === 'Ww') {
        const amount = code === 'xi' ? 500 : 50; 
        await updateBalance(amount, 'GIFT', `Gift Code: ${code}`);
        const userRef = ref(db, `users/${currentUser.uid}`);
        await update(userRef, {
            usedGiftCodes: [...usedCodes, code]
        });
        return amount;
    }
    return 0; 
};

export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { type: 'DEPOSIT', amount, status: 'PROCESSING', desc: `Deposit via ${method}`, utr, method, date: new Date().toLocaleString(), timestamp: serverTimestamp() });
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser || currentUser.balance < amount) return { success: false, message: 'Insufficient balance' };
    const userSnapshot = await get(ref(db, `users/${currentUser.uid}`));
    const userData = userSnapshot.val();
    if (userData.withdrawalPassword !== password) return { success: false, message: 'Incorrect Withdrawal PIN' };
    await updateBalance(-amount, 'WITHDRAW', `Withdraw via ${method}`);
    return { success: true };
};

