};

export const subscribeToChat = (cb: (messages: ChatMessage[]) => void) => {
    const chatRef = query(ref(db, 'chat'), limitToLast(50));
    return onValue(chatRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val).map(([id, m]: [string, any]) => ({ id, ...m }));
            cb(list);
        } else cb([]);
    });
};

