    });
};

export const getLeaderboard = (cb: (users: UserProfile[]) => void) => {
    const usersRef = ref(db, 'users');
    return onValue(usersRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val).map(([uid, u]: [string, any]) => ({ uid, ...u }));
            // Sort by assets + total deposit for real elite ranking
            list.sort((a, b) => (b.balance + b.totalDeposit) - (a.balance + a.totalDeposit));
            cb(list.slice(0, 50));
        } else cb([]);
    });
};

