import React, { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Wallet, Volume2, VolumeX, TrendingUp, History } from 'lucide-react';
import { updateBalance, playSound, addGameHistory, stopAllSounds, toggleMute, getMuteStatus, shouldForceLoss } from '../services/mockFirebase';
import { GameResult } from '../types';

interface DogProps {
    onBack: () => void;
    userBalance: number;
    onResult: (result: GameResult) => void;
}

type Difficulty = 'EASY' | 'MEDIUM' | 'HARD' | 'ELITE';

const MULTIPLIERS: Record<Difficulty, number[]> = {
    EASY: [1.2, 1.5, 1.9, 2.4, 3.1, 4.0, 5.2, 7.0, 9.5],
    MEDIUM: [1.4, 2.1, 3.2, 4.8, 7.5, 12.0, 18.0, 30.0, 50.0],
    HARD: [2.5, 6.0, 15.0, 40.0, 100.0, 250.0, 600.0, 1500.0, 5000.0],
    ELITE: [5.0, 25.0, 125.0, 625.0, 3125.0, 15000.0, 80000.0, 400000.0, 999999.0]
};

const DogRoad: React.FC<DogProps> = ({ onBack, userBalance, onResult }) => {
    const [gameState, setGameState] = useState<'IDLE' | 'PLAYING' | 'CRASHING' | 'CRASHED' | 'WON'>('IDLE');
    const [currentLane, setCurrentLane] = useState(-1);
    const [betAmount, setBetAmount] = useState(10);
    const [difficulty, setDifficulty] = useState<Difficulty>('MEDIUM');
    const [muted, setMuted] = useState(getMuteStatus());
    const [crashLane, setCrashLane] = useState<number | null>(null);
    const isMounted = useRef(true);

    useEffect(() => {
        isMounted.current = true;
        return () => { isMounted.current = false; stopAllSounds(); };
    }, []);

    const startGame = () => {
        if (betAmount > userBalance) { alert("Insufficient Capital!"); return; }
        playSound('click');
        updateBalance(-betAmount, 'BET', 'Dog Road');
        setGameState('PLAYING');
        setCurrentLane(-1);
        setCrashLane(null);
    };

    const nextStep = () => {
        if (gameState !== 'PLAYING') return;
        playSound('click');

        let failChance = 0.15;
        if (difficulty === 'EASY') failChance = 0.1;
        if (difficulty === 'MEDIUM') failChance = 0.2;
        if (difficulty === 'HARD') failChance = 0.45;
        if (difficulty === 'ELITE') failChance = 0.65;

        // Provably Fair check
        const isLoss = Math.random() < failChance || shouldForceLoss(betAmount, userBalance);

        if (isLoss) {
            initiateCrash();
        } else {
            handleSuccess();
        }
    };

    const handleSuccess = () => {
        playSound('win');
        setCurrentLane(prev => prev + 1);
        if (currentLane + 1 >= MULTIPLIERS[difficulty].length - 1) cashOut();
    };

    const initiateCrash = () => {
        const nextLane = currentLane + 1;
        setCrashLane(nextLane);
        setGameState('CRASHING'); 
        playSound('plane_crash'); 
        setTimeout(() => {
            if (!isMounted.current) return;
            setGameState('CRASHED');
            addGameHistory('Dog Road', betAmount, 0, `Hit at Lane ${nextLane}`);
            onResult({ win: false, amount: betAmount, game: 'Dog Road' });
            setTimeout(() => setGameState('IDLE'), 2500);
        }, 800);
    };

    const cashOut = () => {
        if (currentLane === -1) return;
        const mult = MULTIPLIERS[difficulty][currentLane];
        const winAmount = betAmount * mult; 
        updateBalance(winAmount, 'WIN', 'Dog Road Payout');
        addGameHistory('Dog Road', betAmount, winAmount, `Cashed ${mult}x`);
        playSound('win');
        setGameState('WON');
        onResult({ win: true, amount: winAmount, game: 'Dog Road', resultDetails: [{ label: 'Captured', value: `${mult}x` }] });
        setTimeout(() => setGameState('IDLE'), 2500);
    };

    const currentMult = currentLane === -1 ? 1.0 : MULTIPLIERS[difficulty][currentLane];
    const laneWidth = 25; 
    let translateX = currentLane > -1 ? -(currentLane + 1) * laneWidth + laneWidth : 0;

    return (
        <div className="bg-[#0a0f1d] min-h-screen flex flex-col font-sans text-white overflow-hidden relative select-none">
            <div className="p-4 bg-[#111827] flex items-center justify-between border-b border-white/5 z-50">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} disabled={gameState === 'PLAYING'} className="p-2 bg-slate-800 rounded-xl active:scale-90"><ArrowLeft size={18}/></button>
                    <h1 className="font-black text-sm uppercase tracking-widest gold-text italic">DOG ROAD</h1>
                </div>
                <div className="bg-black/50 px-3 py-1.5 rounded-2xl border border-yellow-500/20 text-yellow-500 font-mono text-xs flex items-center gap-2 shadow-inner">
                    <Wallet size={12}/> ₹{userBalance.toFixed(2)}
                </div>
            </div>

            <div className="flex-1 relative bg-[#0f172a] overflow-hidden">
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/asphalt-dark.png')] opacity-30"></div>

                <div 
                    className="absolute inset-y-0 left-0 flex items-center transition-transform duration-500 ease-in-out px-10"
                    style={{ transform: `translateX(${translateX}vw)`, width: `${(MULTIPLIERS[difficulty].length + 1) * laneWidth}vw` }}
                >
                    {/* Start Line */}
                    <div className="w-[25vw] h-full flex-shrink-0 border-r-4 border-white/20 flex flex-col items-center justify-center relative bg-black/20">
                        <div className="text-4xl">🏁</div>
                        {currentLane === -1 && gameState === 'PLAYING' && (
                            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce text-5xl">🐕</div>
                        )}
                    </div>

                    {/* Lanes */}
                    {MULTIPLIERS[difficulty].map((m, i) => (
                        <div key={i} className="w-[25vw] h-full flex-shrink-0 border-r border-dashed border-white/5 relative flex flex-col items-center justify-center group">
                            <div className={`w-20 h-20 rounded-full border-4 flex items-center justify-center transition-all duration-300 ${currentLane >= i ? 'bg-green-500/20 border-green-500' : 'bg-black/40 border-white/10'}`}>
                                <span className={`font-black text-xl italic ${currentLane >= i ? 'text-green-400' : 'text-slate-600'}`}>{m}x</span>
                            </div>

                            {currentLane === i && gameState === 'PLAYING' && (
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 animate-bounce text-5xl z-10 drop-shadow-2xl">🐕</div>
                            )}

                            {crashLane === i && (
                                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-20 animate-in zoom-in">
                                    <div className="text-6xl transform scale-x-[-1] animate-pulse">🚔</div>
                                    <div className="absolute top-0 left-0 text-3xl animate-ping">💥</div>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            <div className="bg-[#111827] p-6 pb-12 border-t border-white/10 z-50">
                {gameState === 'IDLE' ? (
                    <div className="space-y-6">
                        <div className="flex gap-2 p-1 bg-black/40 rounded-2xl border border-white/5">
                            {(['EASY', 'MEDIUM', 'HARD', 'ELITE'] as Difficulty[]).map(d => (
                                <button key={d} onClick={() => setDifficulty(d)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${difficulty === d ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>{d}</button>
                            ))}
                        </div>
                        <div className="flex gap-4">
                            <div className="flex-1 bg-black/40 p-4 rounded-3xl border border-white/5 shadow-inner">
                                <p className="text-[8px] text-slate-500 uppercase font-black mb-1">Stake</p>
                                <input type="number" value={betAmount} onChange={e => setBetAmount(Number(e.target.value))} className="bg-transparent w-full outline-none font-black text-xl italic" />
                            </div>
                            <button onClick={startGame} className="flex-[2] py-6 bg-gradient-to-r from-green-600 to-emerald-700 rounded-3xl font-black text-2xl uppercase tracking-[0.4em] shadow-xl border-t-2 border-white/20 active:scale-95 transition-all">S PRINT</button>
                        </div>
                    </div>
                ) : (
                    <div className="flex gap-4 animate-in slide-in-from-bottom duration-500">
                        <button onClick={cashOut} disabled={currentLane === -1 || gameState !== 'PLAYING'} className={`flex-1 py-6 rounded-3xl font-black uppercase tracking-widest shadow-xl flex flex-col items-center justify-center gap-1 transition-all active:scale-95 ${currentLane === -1 ? 'bg-zinc-800 text-zinc-600' : 'bg-orange-500 text-black shadow-orange-900/40 border-t-2 border-white/30'}`}>
                            <span className="text-sm">CAPTURE</span>
                            <span className="text-lg italic font-mono">₹{(betAmount * currentMult).toFixed(2)}</span>
                        </button>
                        <button onClick={nextStep} disabled={gameState !== 'PLAYING'} className="flex-[2] py-6 bg-gradient-to-r from-green-500 to-blue-600 rounded-3xl font-black text-2xl uppercase tracking-[0.4em] shadow-xl border-t-2 border-white/20 active:scale-95 transition-all animate-pulse">
                            JUMP
                        </button>
                    </div>
                )}
            </div>
            <style>{`.gold-text { background: linear-gradient(to bottom, #fde68a, #d97706, #fde68a); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }`}</style>
        </div>
    );
};
export default DogRoad;

