// Fix: Ensure getGameHistory and getTransactionHistory match listener expectations
export const getGameHistory = (game: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) return () => {};
    const historyRef = ref(db, `game_history/${currentUser.uid}`);
    return onValue(historyRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val).map(([id, h]: [string, any]) => ({ id, ...h }))
                .filter((h: any) => game === 'ALL' || h.game === game);
            cb(list.reverse());
        } else cb([]);
    });
};

export const getTransactionHistory = (cb: (data: Transaction[]) => void) => {
    if (!currentUser) return () => {};
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    return onValue(txRef, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.entries(val).map(([id, t]: [string, any]) => ({ id, ...t }));
            cb(list.reverse());
        } else cb([]);
    });
};

