};

const initSession = () => {
    onAuthStateChanged(auth, async (user) => {
        if (user) {
            const userRef = ref(db, `users/${user.uid}`);
            onValue(userRef, (snapshot) => {
                const data = snapshot.val();
                if (data) {
                    currentUser = {
                        ...data,
                        uid: user.uid,
                        balance: data.balance || 0,
                        email: user.email || data.email,
                    };
                    calculateReferralStats(currentUser!.inviteCode);
                    notifySubscribers();
                }
            }, (error) => {
                console.error("Firebase Read Error:", error);
            });
        } else {
            currentUser = null;
            notifySubscribers();
        }
    });
};

export const login = async (phone: string, email: string, pass: string) => {
    try {
        const userCredential = await signInWithEmailAndPassword(auth, email, pass);
        const user = userCredential.user;
        const userSnapshot = await get(ref(db, `users/${user.uid}`));
        const userData = userSnapshot.val();
        if (userData && userData.phone === phone) return { success: true };
        else if (userData && userData.phone !== phone) { await signOut(auth); return { success: false, message: 'Phone mismatch' }; }
        return { success: true };
    } catch (error: any) { return { success: false, message: error.message }; }
};

export const register = async (phone: string, email: string, pass: string, inviteCode: string, username: string) => {
    try {
        const userCredential = await createUserWithEmailAndPassword(auth, email, pass);
        const user = userCredential.user;
        const myInviteCode = Math.floor(10000000 + Math.random() * 90000000).toString();
        const userData = {
            username, name: username, phone, email, password: pass,
            balance: 0, vipLevel: 0, totalDeposit: 0, totalBet: 0, inviteCode: myInviteCode,
            invitedBy: inviteCode || '', wagerRequired: 0, isBankBound: false, isUpiBound: false,
            isTelegramJoined: false, avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.uid}`,
            createdAt: new Date().toISOString(),
            usedGiftCodes: []
        };
        await set(ref(db, `users/${user.uid}`), userData);
        return { success: true };
    } catch (error: any) { return { success: false, message: error.message }; }
};

export const logout = async () => { await signOut(auth); };
