const notifySubscribers = () => {
    balanceSubscribers.forEach(cb => cb(currentUser ? { ...currentUser } : null));
};

const initSession = () => {
    onAuthStateChanged(auth, async (user) => {
        if (user) {
            const userRef = ref(db, `users/${user.uid}`);
            onValue(userRef, (snapshot) => {
                const data = snapshot.val();
                if (data) {
                    currentUser = {
                        ...data,
                        uid: user.uid,
                        balance: data.balance || 0,
                        email: user.email || data.email,
                    };
                    calculateReferralStats(currentUser!.inviteCode);
                    notifySubscribers();
                }
            }, (err) => {
                console.error("Profile Denied", err);
                if (!currentUser) {
                   currentUser = { uid: user.uid, username: 'Elite User', balance: 0, totalDeposit: 0, totalBet: 0, inviteCode: '', wagerRequired: 0, avatar: '', email: user.email || '', name: 'User', phone: '', vipLevel: 0 };
                   notifySubscribers();
                }
            });
        } else {
            currentUser = null;
            notifySubscribers();
        }
    });
};

export const login = async (phone: string, email: string, pass: string) => {
