export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Not logged in' };
    if (currentUser.withdrawalPassword && currentUser.withdrawalPassword !== password) return { success: false, message: 'Invalid Security PIN' };
    if (currentUser.balance < amount) return { success: false, message: 'Insufficient balance' };

    await updateBalance(-amount, 'WITHDRAW', `Withdrawal via ${method}`);
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { type: 'WITHDRAW', amount, status: 'PENDING', desc: `Processing ${method} Withdrawal`, date: new Date().toLocaleString(), timestamp: serverTimestamp(), accountDetails: details });

    return { success: true, message: 'Request submitted. Assets arriving in 10-30 mins.' };
};

