                id: u.uid || 'N/A', uid: u.uid || 'N/A', level: 1, depositAmount: u.totalDeposit || 0, betAmount: u.totalBet || 0, commission: (u.totalDeposit || 0) * 0.1, date: u.createdAt || 'N/A'
            }));
            cb(subs);
        } else cb([]);
    }, () => cb([]));
};

