import React, { useState, useEffect } from 'react';
import { ArrowLeft, Building2, Smartphone, AlertCircle, ShieldCheck, Lock, ChevronDown, Plus, CheckCircle2 } from 'lucide-react';
import { handleWithdraw, subscribeToBalance } from '../services/mockFirebase';
import { UserProfile } from '../types';

const Withdraw: React.FC<{ onBack: () => void; userBalance: number }> = ({ onBack, userBalance }) => {
    const [amount, setAmount] = useState('');
    const [password, setPassword] = useState('');
    const [method, setMethod] = useState<'BANK' | 'UPI'>('BANK');
    const [message, setMessage] = useState<{ type: 'S'|'E', text: string } | null>(null);
    const [user, setUser] = useState<UserProfile | null>(null);
    const [useBound, setUseBound] = useState(true);

    const [newBank, setNewBank] = useState({ accountName: '', accountNo: '', ifsc: '' });
    const [newUpi, setNewUpi] = useState('');

    useEffect(() => {
        const unsub = subscribeToBalance(u => setUser(u));
        return unsub;
    }, []);

    const showMsg = (text: string, type: 'S'|'E' = 'E') => {
        setMessage({ text, type });
        setTimeout(() => setMessage(null), 4000);
    };

    const onSubmit = async () => {
        if (!user) return;
        const val = parseFloat(amount);
        if (isNaN(val) || val < 110) return showMsg('Minimum withdrawal is ₹110');
        if (user.wagerRequired > 0) return showMsg(`Turnover incomplete! ₹${user.wagerRequired.toFixed(2)} left.`);
        if (!password) return showMsg('Enter Security PIN');

        let details = {};
        if (useBound) {
            if (method === 'BANK' && user.isBankBound) details = user.bankDetails!;
            else if (method === 'UPI' && user.isUpiBound) details = user.upiDetails!;
            else return showMsg('Bound channel not found. Enter manually.');
        } else {
            if (method === 'BANK') {
                if (!newBank.accountNo) return showMsg('Enter bank details');
                details = newBank;
            } else {
                if (!newUpi) return showMsg('Enter UPI ID');
                details = { upiId: newUpi };
            }
        }

        const res = await handleWithdraw(val, method, password, details);
        if (res.success) {
            showMsg(res.message, 'S');
            setAmount('');
            setPassword('');
        } else showMsg(res.message);
    };

    return (
        <div className="bg-[#0a0f1d] min-h-screen text-white font-sans flex flex-col pb-10">
            <div className="p-4 bg-[#111827] flex items-center justify-between border-b border-slate-800 sticky top-0 z-50">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="p-2 bg-slate-800 rounded-full active:scale-90"><ArrowLeft size={18}/></button>
                    <h1 className="font-black text-sm uppercase tracking-widest italic gold-text">CASH OUT ASSETS</h1>
                </div>
            </div>

            <div className="p-6 space-y-6">
                <div className="bg-gradient-to-br from-indigo-600 to-blue-900 rounded-[2.5rem] p-8 relative overflow-hidden shadow-2xl">
                    <p className="text-blue-100 text-[10px] mb-2 uppercase tracking-[0.3em] font-black">Capital</p>
                    <h2 className="text-5xl font-black italic tracking-tighter">₹{userBalance.toFixed(2)}</h2>
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <Tab active={method === 'BANK'} onClick={() => setMethod('BANK')} icon={<Building2 size={32}/>} label="Bank" />
                    <Tab active={method === 'UPI'} onClick={() => setMethod('UPI')} icon={<Smartphone size={32}/>} label="UPI ID" />
                </div>

                <div className="bg-[#111827] border-2 border-slate-800 rounded-3xl p-6 space-y-4">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Payout Target</span>
                        <ShieldCheck size={16} className={method === 'BANK' ? (user?.isBankBound ? 'text-green-500' : 'text-slate-700') : (user?.isUpiBound ? 'text-green-500' : 'text-slate-700')} />
                    </div>
                    {method === 'BANK' ? (
                        user?.isBankBound ? (
                            <div className="bg-black/30 p-4 rounded-2xl border border-green-500/20">
                                <p className="text-sm font-black">{user.bankDetails?.accountName}</p>
                                <p className="text-[10px] text-slate-500 mt-1 uppercase">Bound Account: {user.bankDetails?.accountNo.slice(-4)}</p>
                            </div>
                        ) : <ManualInput label="Bank Holder" value={newBank.accountName} onChange={v => setNewBank({...newBank, accountName: v})} />
                    ) : (
                        user?.isUpiBound ? (
                            <div className="bg-black/30 p-4 rounded-2xl border border-green-500/20">
                                <p className="text-sm font-black">{user.upiDetails?.upiId}</p>
                                <p className="text-[10px] text-slate-500 mt-1 uppercase">Elite Verified UPI</p>
                            </div>
                        ) : <ManualInput label="UPI ID" value={newUpi} onChange={setNewUpi} />
                    )}
                </div>

                <div className="space-y-6">
                    <div className="bg-[#111827] border-2 border-slate-800 rounded-3xl p-5 flex items-center gap-4">
                        <span className="text-yellow-500 font-black text-2xl">₹</span>
                        <input type="number" value={amount} onChange={e => setAmount(e.target.value)} placeholder="Min 110" className="bg-transparent w-full outline-none font-black text-3xl" />
                    </div>
                    <div className="bg-[#111827] border-2 border-slate-800 rounded-3xl p-5 flex items-center gap-4">
                        <Lock size={24} className="text-slate-600" />
                        <input type="password" value={password} onChange={e => setPassword(e.target.value.replace(/\D/g,''))} placeholder="PIN" maxLength={6} className="bg-transparent w-full outline-none font-black text-3xl tracking-[0.4em]" />
                    </div>

                    {message && (
                        <div className={`p-4 rounded-2xl flex items-center gap-3 border ${message.type === 'S' ? 'bg-green-600/10 border-green-500 text-green-400' : 'bg-red-600/10 border-red-500 text-red-400'}`}>
                            {message.type === 'S' ? <CheckCircle2 size={20}/> : <AlertCircle size={20}/>}
                            <p className="text-xs font-black uppercase">{message.text}</p>
                        </div>
                    )}

                    <button onClick={onSubmit} className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 py-6 rounded-3xl font-black uppercase tracking-[0.3em] shadow-2xl active:scale-95 border-t-2 border-white/20">CONFIRM PAYOUT</button>
                </div>
            </div>
        </div>
    );
};

