const GameResultPopup: React.FC<{ result: GameResult | null; onClose: () => void; }> = ({ result, onClose }) => {
    const [visible, setVisible] = useState(false);

    useEffect(() => { 
        if (result) { 
            setVisible(true); 
            const duration = result.game === 'Plinko' ? 1000 : 4000;
            const t = setTimeout(handleClose, duration); 
            return () => clearTimeout(t); 
        } 
    }, [result]);

    const handleClose = () => { 
        setVisible(false); 
        setTimeout(onClose, 300); 
    };

    if (!result && !visible) return null;

    if (result?.win) {
        return (
            <Overlay visible={visible}>
                <div className="w-[85vw] max-w-sm bg-gradient-to-b from-[#fcd34d] to-[#d97706] rounded-[2.5rem] p-1 shadow-[0_0_100px_rgba(217,119,6,0.6)] relative">
                    <div className="bg-[#111827] rounded-[2.4rem] p-8 text-center border border-white/10 overflow-hidden relative">
                        <div className="flex justify-center mb-6">
                            <div className="bg-yellow-500/20 p-5 rounded-full border border-yellow-500/30 relative">
                                <Trophy size={64} className="text-yellow-500 fill-yellow-500/10 drop-shadow-[0_0_20px_rgba(234,179,8,0.5)]" />
                                <div className="absolute -top-1 -right-1 bg-white rounded-full p-1"><Star size={16} className="text-yellow-600 fill-yellow-600"/></div>
