                    <Wallet size={12}/> ₹{userBalance.toFixed(2)}
                </div>
            </div>

            <div className="flex-1 relative overflow-hidden bg-[#0f172a] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
                <div className="absolute top-4 left-1/2 -translate-x-1/2 z-40 bg-black/60 px-4 py-1.5 rounded-full border border-white/10 backdrop-blur-md">
                    <span className="text-xl font-black italic gold-text">{currentMultiplier.toFixed(2)}x</span>
                </div>

                <div 
                    className="absolute inset-y-0 left-0 flex items-center transition-transform duration-500 ease-in-out px-10"
                    style={{ transform: `translateX(${translateX}vw)`, width: `${(MULTIPLIERS[difficulty].length + 1) * laneWidthVW}vw` }}
                >
                    <div className="w-[25vw] h-full flex-shrink-0 bg-zinc-900/40 border-r-4 border-white/10 relative flex flex-col justify-center items-center z-10 shadow-[20px_0_40px_rgba(0,0,0,0.4)]">
