                                    <input type="number" value={betAmount} onChange={e => setBetAmount(Number(e.target.value))} className="bg-transparent w-full outline-none font-black text-xl italic" />
                                </div>
                            </div>
                            <button onClick={startGame} className="flex-[1.5] py-6 bg-gradient-to-r from-green-600 to-emerald-700 rounded-[2rem] font-black text-2xl uppercase tracking-[0.4em] shadow-2xl border-t-2 border-white/20 active:scale-95 transition-all flex items-center justify-center gap-3">
                                <PlayCircle size={28}/> GO
