    if (!currentUser || (currentUser.totalBet || 0) <= 0) return { success: false, message: 'No rebate available' };

    const rebateAmount = (currentUser.totalBet || 0) * 0.001; // 0.1% Rebate
    const userRef = ref(db, `users/${currentUser.uid}`);

    // Add reward to balance and reset the turnover counter
    await update(userRef, {
        balance: (currentUser.balance || 0) + rebateAmount,
        totalBet: 0 // Reset turnover for next cycle
    });

    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { 
        type: 'BONUS', 
        amount: rebateAmount, 
        status: 'SUCCESS', 
        desc: 'Betting Rebate Claimed', 
        date: new Date().toLocaleString(), 
        timestamp: serverTimestamp() 
    });

    return { success: true, amount: rebateAmount };
};

