export const getGameHistory = (game: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) {
        cb([]);
        return () => {};
    }
    const historyRef = ref(db, `game_history/${currentUser.uid}`);
    const q = query(historyRef, orderByChild('timestamp'), limitToLast(50));
    return onValue(q, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            let list = Object.entries(val).map(([id, h]: [string, any]) => ({ id, ...h }));
            if (game !== 'ALL') {
                list = list.filter(item => item.game === game);
            }
            cb(list.reverse());
        } else {
            cb([]);
        }
    });
};

