export const submitDepositRequest = async (amount: number, method: string, utr: string) => {
    if (!currentUser) return;
    const userRef = ref(db, `users/${currentUser.uid}`);
    const newWager = (currentUser.wagerRequired || 0) + (amount * 5.4); // 5.4x wager on deposit
    await update(userRef, { wagerRequired: newWager });

    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { 
        type: 'DEPOSIT', 
        amount, 
        status: 'PROCESSING', 
        desc: `Deposit via ${method}`, 
        utr, 
        method, 
        date: new Date().toLocaleString(), 
        timestamp: serverTimestamp() 
    });
};

export const handleWithdraw = async (amount: number, method: string, password: string, details: any) => {
    if (!currentUser) return { success: false, message: 'Not logged in' };
    if (!currentUser.withdrawalPassword) return { success: false, message: 'Please set your Security PIN first.' };
    if (currentUser.withdrawalPassword !== password) return { success: false, message: 'Invalid Security PIN' };
    if (currentUser.balance < amount) return { success: false, message: 'Insufficient balance' };
    if ((currentUser.wagerRequired || 0) > 0) return { success: false, message: `Wager incomplete! ₹${currentUser.wagerRequired.toFixed(2)} left.` };

    await updateBalance(-amount, 'WITHDRAW', `Withdrawal via ${method}`);
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    await push(txRef, { 
        type: 'WITHDRAW', 
        amount, 
        status: 'PENDING', 
        desc: `Processing ${method} Withdrawal`, 
        date: new Date().toLocaleString(), 
        timestamp: serverTimestamp(), 
        accountDetails: details 
    });

    return { success: true, message: 'Request submitted. Assets arriving in 10-30 mins.' };
};

