export const getGameHistory = (game: string, cb: (data: GameHistoryItem[]) => void) => {
    if (!currentUser) return cb([]);
    const historyRef = ref(db, `game_history/${currentUser.uid}`);
    const q = query(historyRef, orderByChild('timestamp'), limitToLast(50));
    return onValue(q, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            let list = Object.entries(val).map(([id, h]: [string, any]) => ({ id, ...h }));
            if (game !== 'ALL') list = list.filter(item => item.game === game);
            cb(list.reverse());
        } else cb([]);
    });
};

export const getTransactionHistory = (cb: (data: Transaction[]) => void) => {
    if (!currentUser) return cb([]);
    const txRef = ref(db, `transactions/${currentUser.uid}`);
    const q = query(txRef, orderByChild('timestamp'), limitToLast(50));
    return onValue(q, (snapshot) => {
        const val = snapshot.val();
        if (val) cb(Object.entries(val).map(([id, t]: [string, any]) => ({ id, ...t })).reverse());
        else cb([]);
    });
};

export const getLeaderboard = (cb: (data: UserProfile[]) => void) => {
    const usersRef = ref(db, 'users');
    const q = query(usersRef, orderByChild('totalDeposit'), limitToLast(20));
    return onValue(q, (snapshot) => {
        const val = snapshot.val();
        if (val) {
            const list = Object.values(val) as UserProfile[];
            list.sort((a, b) => (b.balance + (b.totalDeposit || 0)) - (a.balance + (a.totalDeposit || 0)));
            cb(list);
        } else cb([]);
    });
};

export const approveTransaction = async (txId: string) => {
    if (!currentUser) return;
    const txRef = ref(db, `transactions/${currentUser.uid}/${txId}`);
    const snapshot = await get(txRef);
    const tx = snapshot.val();
    if (tx && tx.status === 'PROCESSING') {
        await update(txRef, { status: 'SUCCESS' });
        if (tx.type === 'DEPOSIT') {
            const userRef = ref(db, `users/${currentUser.uid}`);
            const newBalance = (currentUser.balance || 0) + tx.amount;
            const newTotalDeposit = (currentUser.totalDeposit || 0) + tx.amount;
            const thresholds = [500, 2000, 50000, 100000, 400000];
            let newVipLevel = 0;
            thresholds.forEach((t, i) => { if (newTotalDeposit >= t) newVipLevel = i + 1; });
            await update(userRef, { balance: newBalance, totalDeposit: newTotalDeposit, vipLevel: newVipLevel });
            playSound('win');
        }
    }
};

