                <div className="relative w-full flex flex-wrap justify-center content-start gap-1 h-full overflow-y-auto no-scrollbar">
                    {andarCards.map((c) => <FullCard key={c.id} card={c} />)}
                </div>
            </div>
            <div className="flex flex-col items-center bg-black/10 rounded-3xl p-4 border border-white/5">
                <span className="text-[9px] font-black uppercase text-blue-400 tracking-widest mb-4">BAHAR</span>
                <div className="relative w-full flex flex-wrap justify-center content-start gap-1 h-full overflow-y-auto no-scrollbar">
                    {baharCards.map((c) => <FullCard key={c.id} card={c} />)}
                </div>
            </div>
        </div>
      </div>

      {/* FIXED FOOTER CONTROLS */}
      <div className="fixed bottom-0 left-0 w-full bg-[#111] p-6 pb-10 border-t border-white/10 shadow-[0_-20px_60px_rgba(0,0,0,1)] z-[60]">
