export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser) return 0;

    // Check dynamic gift codes
    const codeRef = ref(db, `gift_codes/${code}`);
    const codeSnap = await get(codeRef);
    const codeData = codeSnap.val() as GiftCode;

    if (!codeData) return 0; // Invalid code

    const userSnapshot = await get(ref(db, `users/${currentUser.uid}`));
    const userData = userSnapshot.val();
    const usedCodes = userData.usedGiftCodes || [];

    if (usedCodes.includes(code)) return -1; // Already used
    if (codeData.usedCount >= codeData.limit) return -2; // Limit reached
    if (userData.vipLevel < codeData.minVip) return -3; // VIP too low

    const amount = codeData.amount;
    if (amount > 0) {
        await updateBalance(amount, 'GIFT', `Redeemed: ${code}`);
        await update(ref(db, `users/${currentUser.uid}`), { usedGiftCodes: [...usedCodes, code] });
        await update(codeRef, { usedCount: codeData.usedCount + 1 });
        return amount;
    }
    return 0;
};

