export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser) return 0;

    const codeRef = ref(db, `gift_codes/${code}`);
    const codeSnap = await get(codeRef);
    const codeData = codeSnap.val() as GiftCode;

    if (!codeData) return 0; 

    const userSnapshot = await get(ref(db, `users/${currentUser.uid}`));
    const userData = userSnapshot.val();
    const usedCodes = userData.usedGiftCodes || [];

    if (usedCodes.includes(code)) return -1; 
    if (codeData.usedCount >= codeData.limit) return -2; 
    if (userData.vipLevel < codeData.minVip) return -3; 

    const amount = codeData.amount;
    if (amount > 0) {
