        if (!val) return cb([]);
        const players = Object.entries(val).map(([uid, u]: any) => ({ ...u, uid }));
        players.sort((a, b) => (b.balance + (b.totalDeposit || 0)) - (a.balance + (a.totalDeposit || 0)));
        cb(players.slice(0, 20));
    });
};

