export default function App() {
  const [currentView, setCurrentView] = useState<View | 'ADMIN'>('HOME');
  const [user, setUser] = useState<UserProfile | null>(null);
  const [gameResult, setGameResult] = useState<GameResult | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => { 
      startGlobalEngines(); 
  }, []);

  useEffect(() => { 
      stopAllSounds(); 
  }, [currentView]);

  useEffect(() => {
    const unsubscribe = subscribeToBalance((updatedUser) => {
        setUser(updatedUser);
        setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  if (isLoading) return (
    <div className="min-h-screen bg-[#0a0f1d] flex items-center justify-center">
      <div className="w-12 h-12 border-4 border-yellow-500 border-t-transparent rounded-full animate-spin"></div>
    </div>
  );

  if (!user && currentView !== 'LOGIN' && currentView !== 'REGISTER') {
    return <Auth />;
  }

  const renderContent = () => {
    if (!user) return <Auth />;

    switch (currentView) {
      case 'HOME': return <Home setView={setCurrentView} />;
      case 'ADMIN': return <AdminPanel onBack={() => setCurrentView('ACCOUNT')} />;
      case 'GAME_WINGO': return <WinGo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} setView={setCurrentView} />;
      case 'GAME_AVIATOR': return <Aviator onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_MINES': return <Mines onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DRAGON_TIGER': return <DragonTiger onBack={() => setCurrentView('HOME')} userBalance={user.balance} username={user.username} onResult={setGameResult} />;
      case 'GAME_ROULETTE': return <Roulette onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_SICBO': return <SicBo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_BACCARAT': return <Baccarat onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_STREET_RACE': return <StreetRace onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_VAULT': return <VaultBreaker onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_FRUIT_SLOT': return <FruitSlot onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_EGYPT_SLOT': return <EgyptSlot onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DICE': return <DiceDuel onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_MOTO_RACING': return <MotoRacing onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_PLINKO': return <Plinko onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_LIMBO': return <Limbo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_HILO': return <HiLo onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DRAGON_TOWER': return <DragonTower onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_KENO': return <Keno onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_HEAD_TAILS': return <HeadTails onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_BURST': return <CyberBurst onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_DOG': return <DogRoad onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_VORTEX': return <Vortex onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_PENALTY': return <Penalty onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_CRICKET': return <Cricket onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_TOWER': return <Tower onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_SLOT_MACHINE': return <SlotMachine onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'GAME_ANDAR_BAHAR': return <AndarBahar onBack={() => setCurrentView('HOME')} userBalance={user.balance} onResult={setGameResult} />;
      case 'LEADERBOARD': return <Leaderboard onBack={() => setCurrentView('HOME')} />;
      case 'CHAT': return <LiveChat onBack={() => setCurrentView('HOME')} />;
      case 'ACCOUNT': return <Profile user={user} setView={setCurrentView} />;
      case 'REFERRAL': return <Referral user={user} />;
      case 'PROMOTION': return <Promotion />;
      case 'WALLET': return <Wallet setView={setCurrentView} userBalance={user.balance} />;
      case 'DEPOSIT': return <Deposit onBack={() => setCurrentView('WALLET')} />;
      case 'WITHDRAW': return <Withdraw onBack={() => setCurrentView('WALLET')} userBalance={user.balance} />;
      case 'SAFETY': return <SafetyCenter setView={setCurrentView} user={user} />;
      case 'STATISTICS': return <GameStatistics setView={setCurrentView} />;
      case 'REWARDS_HUB': return <BindingRewards onBack={() => setCurrentView('ACCOUNT')} />;
      default: return <Home setView={setCurrentView} />;
    }
  };

  const showNavBar = ['HOME', 'REFERRAL', 'PROMOTION', 'WALLET', 'ACCOUNT'].includes(currentView);

  return (
    <div className="max-w-md mx-auto min-h-screen bg-[#0a0f1d] shadow-2xl relative overflow-hidden font-sans border-x border-white/5">
      {showNavBar && <DownloadBanner />}
      {renderContent()}
      <GameResultPopup result={gameResult} onClose={() => setGameResult(null)} />
      {showNavBar && <NavBar currentView={currentView as View} setView={setCurrentView} />}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { UserProfile, GiftCode, AppSettings, Transaction } from '../types';
import { getAllUsers, adminUpdateUserBalance, adminBlockUser, adminDeleteUser, adminGetSettings, adminUpdateSettings, adminCreateGiftCode, adminGetAllGiftCodes, getAllPendingTransactions, approveTransaction, rejectTransaction } from '../services/supabaseService';
import { ArrowLeft, Users, Gamepad2, Gift, ShieldCheck, Wallet, Trash2, Ban, Search, CheckCircle2, X, Plus, Power, CreditCard, Clock, CheckCircle } from 'lucide-react';

const AdminPanel: React.FC<{ onBack: () => void }> = ({ onBack }) => {
    const [activeTab, setActiveTab] = useState<'REQUESTS' | 'USERS' | 'GAMES' | 'GIFTS' | 'PAYMENTS'>('REQUESTS');
    const [users, setUsers] = useState<UserProfile[]>([]);
    const [giftCodes, setGiftCodes] = useState<GiftCode[]>([]);
    const [settings, setSettings] = useState<AppSettings | null>(null);
    const [pendingRequests, setPendingRequests] = useState<{uid: string, txId: string, tx: Transaction}[]>([]);
    const [search, setSearch] = useState('');
    const [loading, setLoading] = useState(false);
    const [showGiftModal, setShowGiftModal] = useState(false);
    const [newGift, setNewGift] = useState({ code: '', amount: 100, limit: 10, minVip: 0 });

    useEffect(() => {
        setLoading(true);
        getAllUsers(setUsers);
        adminGetAllGiftCodes(setGiftCodes);
        getAllPendingTransactions(setPendingRequests);
        const unsub = adminGetSettings(setSettings);
        setLoading(false);
        return unsub;
    }, []);

    const handleMoneyAction = async (uid: string, amount: number, isGift: boolean) => {
        if (window.confirm(isGift ? `Gift ₹${amount}?` : `Deduct ₹${Math.abs(amount)}?`)) {
            await adminUpdateUserBalance(uid, amount, isGift);
        }
    };

    const toggleGame = async (gameId: string) => {
        if (!settings) return;
        const newDisabled = { ...settings.disabledGames };
        newDisabled[gameId] = !newDisabled[gameId];
        await adminUpdateSettings({ disabledGames: newDisabled });
    };

    const filteredUsers = users.filter(u => 
        u.username?.toLowerCase().includes(search.toLowerCase()) || 
        u.phone?.includes(search)
    );

    return (
        <div className="min-h-screen bg-[#0a0f1d] text-white font-sans flex flex-col">
            <div className="bg-[#111827] p-4 flex items-center justify-between border-b border-yellow-500/20 sticky top-0 z-50">
                <div className="flex items-center gap-4">
                    <button onClick={onBack} className="p-2 bg-slate-800 rounded-xl"><ArrowLeft size={20}/></button>
                    <h1 className="text-lg font-black gold-text uppercase italic">MASTER COMMAND</h1>
                </div>
                <div className="bg-yellow-500/10 px-3 py-1 rounded-full border border-yellow-500/20 text-[10px] font-black uppercase text-yellow-500">Live Control</div>
            </div>

            <div className="flex bg-[#111827] border-b border-white/5 overflow-x-auto no-scrollbar">
                <NavBtn label="Requests" active={activeTab === 'REQUESTS'} onClick={() => setActiveTab('REQUESTS')} badge={pendingRequests.length} />
                <NavBtn label="Users" active={activeTab === 'USERS'} onClick={() => setActiveTab('USERS')} />
                <NavBtn label="Games" active={activeTab === 'GAMES'} onClick={() => setActiveTab('GAMES')} />
                <NavBtn label="Gift" active={activeTab === 'GIFTS'} onClick={() => setActiveTab('GIFTS')} />
                <NavBtn label="Config" active={activeTab === 'PAYMENTS'} onClick={() => setActiveTab('PAYMENTS')} />
            </div>

            <div className="flex-1 p-6 overflow-y-auto pb-24">
                {activeTab === 'REQUESTS' && (
                    <div className="space-y-4">
                        {pendingRequests.length > 0 ? pendingRequests.map(({uid, txId, tx}) => (
                            <div key={txId} className="bg-[#111827] p-6 rounded-3xl border border-white/5 shadow-xl relative overflow-hidden">
                                <div className={`absolute top-0 right-0 px-4 py-1 rounded-bl-xl font-black text-[9px] uppercase ${tx.type === 'DEPOSIT' ? 'bg-blue-600' : 'bg-red-600'}`}>{tx.type}</div>
                                <div className="flex justify-between items-start mb-4">
                                    <div>
                                        <h4 className="font-black text-sm text-yellow-500">₹{tx.amount.toFixed(2)}</h4>
                                        <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">Operative: {uid.slice(-6)}</p>
                                        <p className="text-[10px] text-slate-400 mt-2 font-mono">UTR: {tx.utr || 'N/A'}</p>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-[9px] text-slate-500 font-black uppercase">Channel</p>
                                        <p className="text-[10px] font-black text-white">{tx.method || 'Direct'}</p>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-3 mt-4">
                                    <button onClick={() => approveTransaction(uid, txId)} className="py-3 bg-green-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest active:scale-95 shadow-lg shadow-green-900/20">APPROVE</button>
                                    <button onClick={() => rejectTransaction(uid, txId)} className="py-3 bg-red-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest active:scale-95 shadow-lg shadow-red-900/20">REJECT</button>
                                </div>
                            </div>
                        )) : (
                            <div className="py-20 flex flex-col items-center opacity-20">
                                <Clock size={48} className="mb-4" />
                                <p className="font-black uppercase tracking-widest">No Pending Requests</p>
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'USERS' && (
                    <div className="space-y-4">
                        <div className="bg-zinc-900 rounded-2xl p-3 flex items-center gap-3 border border-white/10 mb-6">
                            <Search size={18} className="text-slate-500" />
                            <input type="text" placeholder="Alias or Phone..." value={search} onChange={(e) => setSearch(e.target.value)} className="bg-transparent flex-1 text-sm outline-none text-white" />
                        </div>
                        {filteredUsers.map(u => (
                            <div key={u.uid} className="bg-[#111827] p-6 rounded-3xl border border-white/5">
                                <div className="flex justify-between items-center mb-4">
                                    <div className="flex items-center gap-3">
                                        <img src={u.avatar} className="w-10 h-10 rounded-full" />
                                        <div><h3 className="font-black text-sm">@{u.username}</h3><p className="text-[9px] text-slate-500">{u.phone}</p></div>
                                    </div>
                                    <div className="text-right"><p className="text-lg font-black gold-text">₹{u.balance.toFixed(2)}</p></div>
                                </div>
