// FIX: Improved redeemGiftCode to use real Database values
export const redeemGiftCode = async (code: string): Promise<number> => {
    if (!currentUser) return 0;
    const giftRef = ref(db, `gift_codes/${code}`);
    const snap = await get(giftRef);
    const gift = snap.val() as GiftCode;
    if (!gift) return 0;
    if (currentUser.usedGiftCodes?.includes(code)) return -1;
    if (gift.usedCount >= gift.limit) return -2;
    if (currentUser.vipLevel < gift.minVip) return -3;
    const userRef = ref(db, `users/${currentUser.uid}`);
    const newUsed = [...(currentUser.usedGiftCodes || []), code];
    await update(userRef, { balance: (currentUser.balance || 0) + gift.amount, usedGiftCodes: newUsed });
    await update(giftRef, { usedCount: gift.usedCount + 1 });
    await updateBalance(gift.amount, 'GIFT', `Gift Code: ${code}`);
    return gift.amount;
};

