// GAME ENGINES
let winGoState: WinGoGameState = { timeLeft: 30, period: 202511261000, history: [], status: 'BETTING', lastResult: null };
const winGoSubscribers: Function[] = [];
const generateWinGoResult = (period: string): WinGoHistory => {
  const num = Math.floor(Math.random() * 10);
  let color: 'Red'|'Green'|'Violet' = 'Red';
  if (num === 0 || num === 5) color = 'Violet';
  else if ([1,3,7,9].includes(num)) color = 'Green';
  return { period, number: num, bigSmall: num >= 5 ? 'Big' : 'Small', color };
};
const startWinGoGame = () => {
  if (winGoState.history.length === 0) for(let i=0; i<10; i++) winGoState.history.unshift(generateWinGoResult((winGoState.period - 10 + i).toString()));
  setInterval(() => {
    winGoState.timeLeft -= 1;
    if (winGoState.timeLeft <= 0) {
        winGoState.status = 'REVEALING';
        const res = generateWinGoResult(winGoState.period.toString());
        winGoState.lastResult = res;
        winGoState.history = [res, ...winGoState.history].slice(0, 50);
        winGoState.period += 1;
        winGoState.timeLeft = 30;
        setTimeout(() => { winGoState.status = 'BETTING'; winGoSubscribers.forEach(cb => cb({ ...winGoState })); }, 3000);
    }
    winGoSubscribers.forEach(cb => cb({ ...winGoState }));
  }, 1000);
};
export const subscribeToWinGo = (cb: (state: WinGoGameState) => void) => { winGoSubscribers.push(cb); cb(winGoState); return () => winGoSubscribers.splice(winGoSubscribers.indexOf(cb), 1); };

// FIX: Added missing Aviator realtime engine
let aviatorState: AviatorState = { phase: 'WAITING', multiplier: 1.0, timeLeft: 5, history: [], crashPoint: 0 };
const aviatorSubscribers: Function[] = [];
const startAviatorEngine = () => {
    setInterval(() => {
        if (aviatorState.phase === 'WAITING') {
            aviatorState.timeLeft -= 0.1;
            if (aviatorState.timeLeft <= 0) {
                aviatorState.phase = 'FLYING';
                aviatorState.multiplier = 1.0;
                aviatorState.crashPoint = 1 + Math.random() * 5;
            }
        } else if (aviatorState.phase === 'FLYING') {
            aviatorState.multiplier *= 1.02;
            if (aviatorState.multiplier >= aviatorState.crashPoint) {
                aviatorState.phase = 'CRASHED';
                aviatorState.history = [aviatorState.multiplier, ...aviatorState.history].slice(0, 20);
                setTimeout(() => {
                    aviatorState.phase = 'WAITING';
                    aviatorState.timeLeft = 5;
                }, 3000);
            }
        }
        aviatorSubscribers.forEach(cb => cb({ ...aviatorState }));
    }, 100);
};
export const subscribeToAviator = (cb: (state: AviatorState) => void) => { aviatorSubscribers.push(cb); cb(aviatorState); return () => aviatorSubscribers.splice(aviatorSubscribers.indexOf(cb), 1); };

// FIX: Added missing DragonTiger realtime engine
let dtState: DragonTigerState = { status: 'BETTING', timeLeft: 15, period: '1000', dragonCard: null, tigerCard: null, history: [] };
const dtSubscribers: Function[] = [];
const startDragonTigerEngine = () => {
    setInterval(() => {
        dtState.timeLeft -= 1;
        if (dtState.timeLeft <= 0) {
            dtState.status = 'RESULT';
            dtState.dragonCard = Math.floor(Math.random() * 13) + 1;
            dtState.tigerCard = Math.floor(Math.random() * 13) + 1;
            const res = dtState.dragonCard > dtState.tigerCard ? 'D' : dtState.tigerCard > dtState.dragonCard ? 'T' : 'Tie';
            dtState.history = [res, ...dtState.history].slice(0, 20);
            dtState.period = (parseInt(dtState.period) + 1).toString();
            setTimeout(() => {
                dtState.status = 'BETTING';
                dtState.timeLeft = 15;
                dtState.dragonCard = null;
                dtState.tigerCard = null;
                dtSubscribers.forEach(cb => cb({ ...dtState }));
            }, 5000);
        }
        dtSubscribers.forEach(cb => cb({ ...dtState }));
    }, 1000);
};
export const subscribeToDragonTiger = (cb: (state: DragonTigerState) => void) => { dtSubscribers.push(cb); cb(dtState); return () => dtSubscribers.splice(dtSubscribers.indexOf(cb), 1); };

