    if (tx && tx.status === 'PROCESSING') {
        await update(txRef, { status: 'SUCCESS' });
        if (tx.type === 'DEPOSIT') {
            const userRef = ref(db, `users/${uid}`);
            const userSnap = await get(userRef);
            const userData = userSnap.val();
            const newTotalDeposit = (userData.totalDeposit || 0) + tx.amount;
            await update(userRef, {
                balance: (userData.balance || 0) + tx.amount,
                totalDeposit: newTotalDeposit,
                wagerRequired: (userData.wagerRequired || 0) + tx.amount,
                wagerTotal: (userData.wagerTotal || 0) + tx.amount
            });
        }
    }
};

