export const getAllPendingTransactions = (cb: (data: any[]) => void) => {
    const txRootRef = ref(db, 'transactions');
    return onValue(txRootRef, (snapshot) => {
        const allTxs: any[] = [];
        const val = snapshot.val();
        if (val) {
            Object.entries(val).forEach(([uid, userTxs]: [string, any]) => {
                Object.entries(userTxs).forEach(([txId, tx]: [string, any]) => {
                    if (tx.status === 'PROCESSING') allTxs.push({ uid, txId, tx });
                });
            });
        }
        cb(allTxs.reverse());
    });
};

/**
 * UPDATED DYNAMIC ODDS:
 * Default 30% winning chance. 
 * If < 20% wager remains, chance drops to 20%.
 */
export const shouldForceLoss = (betAmount: number, currentBalance: number) => {
    if (!currentUser) return Math.random() < 0.7;
    const wagerRemaining = currentUser.wagerRequired || 0;
    const wagerTotal = currentUser.wagerTotal || 1;
    const isNearCompletion = wagerRemaining > 0 && (wagerRemaining / wagerTotal) < 0.2;
    const lossThreshold = isNearCompletion ? 0.8 : 0.7;
    return Math.random() < lossThreshold;
};

