const initSession = () => {
    onAuthStateChanged(auth, async (user) => {
        if (user) {
            const userRef = ref(db, `users/${user.uid}`);
            onValue(userRef, (snapshot) => {
                const data = snapshot.val();
                if (data) {
                    currentUser = {
                        ...data,
                        uid: user.uid,
                        balance: Number(data.balance) || 0,
                        email: user.email || data.email,
                    };
                    calculateReferralStats(currentUser!.inviteCode);
                    notifySubscribers();
                }
            });

            // Keep local history cache in sync for synchronous getGameStats usage
            const historyRef = ref(db, `game_history/${user.uid}`);
            onValue(historyRef, (snapshot) => {
                const val = snapshot.val();
                localGameHistory = val ? Object.entries(val).map(([id, h]: any) => ({ id, ...h })).reverse() : [];
            });
        } else {
            currentUser = null;
            localGameHistory = [];
            notifySubscribers();
        }
    });
};

