        type: isGift ? 'GIFT' : 'BET',
        amount: Math.abs(amount),
        status: 'SUCCESS',
        desc: isGift ? 'Admin Gift' : 'Admin Deduction',
        date: new Date().toLocaleString(),
        timestamp: serverTimestamp()
