// Listener for all pending transactions across all users
export const getAllPendingTransactions = (cb: (requests: any[]) => void) => {
    return onValue(ref(db, 'transactions'), (snapshot) => {
        const allTxs = snapshot.val();
        if (!allTxs) return cb([]);

        const pending: any[] = [];
        Object.entries(allTxs).forEach(([uid, txs]: [string, any]) => {
            Object.entries(txs).forEach(([txId, tx]: [string, any]) => {
                if (tx && tx.status === 'PROCESSING') {
                    pending.push({ uid, txId, tx });
                }
            });
        });
        cb(pending);
    });
};

// Approve a processing transaction
export const approveTransaction = async (uid: string, txId: string) => {
    const txRef = ref(db, `transactions/${uid}/${txId}`);
    const snap = await get(txRef);
    const tx = snap.val();
    if (!tx || tx.status !== 'PROCESSING') return;

    await update(txRef, { status: 'SUCCESS' });

    if (tx.type === 'DEPOSIT') {
        const userRef = ref(db, `users/${uid}`);
        const userSnap = await get(userRef);
        const user = userSnap.val() as UserProfile;
        if (!user) return;

        const amount = Number(tx.amount);
        const newTotalDeposit = (Number(user.totalDeposit) || 0) + amount;
        const newBalance = (Number(user.balance) || 0) + amount;

        // VIP Level thresholds
        let newVip = Number(user.vipLevel) || 0;
        const thresholds = [500, 2000, 50000, 100000, 400000];
        thresholds.forEach((t, i) => { if (newTotalDeposit >= t) newVip = Math.max(newVip, i + 1); });

        const updates: any = { 
            balance: newBalance, 
            totalDeposit: newTotalDeposit,
            vipLevel: newVip
        };

        // Automatic First Deposit Bonus (20%)
        if ((Number(user.totalDeposit) || 0) === 0) {
             const bonus = amount * 0.20;
             const bonusTxRef = ref(db, `transactions/${uid}`);
             await push(bonusTxRef, { 
                 type: 'BONUS', 
                 amount: bonus, 
                 status: 'SUCCESS', 
                 desc: 'First Deposit Bonus', 
                 date: new Date().toLocaleString(), 
                 timestamp: serverTimestamp() 
             });
             updates.balance += bonus;
        }

        await update(userRef, updates);

        // Process Referral Commission (50% on first deposit)
        if (user.invitedBy) {
            const usersRef = ref(db, 'users');
            const usersSnap = await get(usersRef);
            const users = usersSnap.val();
            const referrer = Object.values(users || {}).find((u: any) => u.inviteCode === user.invitedBy) as any;
            if (referrer) {
                const refUid = referrer.uid;
                const refBonus = amount * 0.5;
                await update(ref(db, `users/${refUid}`), { 
                    balance: (Number(referrer.balance) || 0) + refBonus,
                    totalCommission: (Number(referrer.totalCommission) || 0) + refBonus
                });
                await push(ref(db, `transactions/${refUid}`), { 
                    type: 'COMMISSION', 
                    amount: refBonus, 
                    status: 'SUCCESS', 
                    desc: '50% Referral Bonus', 
                    date: new Date().toLocaleString(), 
                    timestamp: serverTimestamp() 
                });
            }
        }
    }
};

// Reject a processing transaction
export const rejectTransaction = async (uid: string, txId: string) => {
    const txRef = ref(db, `transactions/${uid}/${txId}`);
    const snap = await get(txRef);
    const tx = snap.val();
    if (!tx || tx.status !== 'PROCESSING') return;

    await update(txRef, { status: 'FAILED' });

    // Refund balance if it was a withdrawal
    if (tx.type === 'WITHDRAW') {
        const userRef = ref(db, `users/${uid}`);
        const userSnap = await get(userRef);
        const user = userSnap.val();
        if (user) {
            await update(userRef, { balance: (Number(user.balance) || 0) + Number(tx.amount) });
        }
    }
};

